	["Blanco"] = "Weiß",
	["Blizzard no dejó copiar tu mapa desde un addon. Se abrió su ventana de clic para lanzar: arma ahí los mismos clics."] = "Blizzard erlaubt einem Addon nicht, deine Belegung zu kopieren. Das Klickzauber-Fenster wurde geöffnet: Richte dort dieselben Klicks ein.",
	["Blizzard no dejó copiar tu mapa desde un addon. Ábrelo en el menú del juego: Opciones, Clic para lanzar."] = "Blizzard erlaubt einem Addon nicht, deine Belegung zu kopieren. Öffne sie im Spielmenü: Optionen, Klickzauber.",
