	["Build importado de una cadena. Alfa lo resuelve en tu árbol y te avisa si algún talento no existe."] = "Aus einem Text importierter Build. Alfa ordnet ihn deinem Baum zu und warnt dich, wenn ein Talent nicht existiert.",
	["Builds te dice cuál sigue."] = "Builds zeigt dir, welches als Nächstes dran ist.",
	["Busca al entrenador de tu clase en la ciudad."] = "Such den Lehrer deiner Klasse in der Stadt.",
	["Busca cualquier cosa del juego"] = "Schlag alles im Spiel nach",
	["Busca cualquier cosa, en español o en inglés…"] = "Such nach allem, auf Deutsch oder Englisch…",
	["Busca el arma de dos manos con más daño por segundo: es lo que más sube tu daño."] = "Such die Zweihandwaffe mit dem meisten Schaden pro Sekunde: Das erhöht deinen Schaden am meisten.",
	["Busca el arma de dos manos más lenta y fuerte: tus sellos pegan con ella."] = "Such die langsamste und stärkste Zweihandwaffe: Deine Siegel treffen mit ihr.",
	["Busca la zona de la misión entre las guías de subir de nivel."] = "Such das Gebiet der Quest unter den Levelguides.",
	["Busca lo mejor que puedes usar"] = "Such das Beste, was du nutzen kannst",
	["Busca siempre el arco, arma de fuego o ballesta con más daño por segundo."] = "Such immer den Bogen, die Schusswaffe oder die Armbrust mit dem meisten Schaden pro Sekunde.",
	["Busca un escudo con valor de bloqueo alto: sube el daño de Embate con escudo."] = "Such einen Schild mit hohem Blockwert: Er erhöht den Schaden von Schildschlag.",
