	["Cambias de actitud sin perder ira: puedes pasar a defensiva cuando se complica."] = "Du wechselst die Haltung, ohne Wut zu verlieren: Du kannst in die Verteidigungshaltung gehen, wenn es brenzlig wird.",
	["Camina por el agua: espérenlo en tierra y atráiganlo con un ataque a distancia."] = "Er läuft durchs Wasser: Wartet an Land auf ihn und lockt ihn mit einem Fernangriff an.",
