	["Clic derecho (o Mayús+clic): un marcador ahí. Ctrl+clic: la flecha y la ruta te llevan ahí sin guardar nada."] = "Rechtsklick (oder Umschalt+Klick): eine Markierung dort. Strg+Klick: Pfeil und Route führen dich hin, ohne etwas zu speichern.",
	["Clic derecho: dejarla sin acción."] = "Rechtsklick: ohne Aktion lassen.",
	["Clic derecho: opciones de esta guía"] = "Rechtsklick: Optionen dieses Guides",
	["Clic en un marcador: su ficha (cambiarlo, compartirlo, borrarlo o seguirlo). Mayús+clic: seguirlo de una vez. Clic derecho en cualquier otro pin: seguirlo o guardarlo como marcador."] = "Klick auf eine Markierung: ihr Eintrag (ändern, teilen, löschen oder folgen). Umschalt+Klick: sofort folgen. Rechtsklick auf jeden anderen Pin: folgen oder als Markierung speichern.",
	["Clic en una casilla para elegir qué hace sobre el compañero bajo tu ratón; clic derecho la deja sin acción. Los cambios se aplican fuera de combate."] = "Klick auf ein Feld, um zu wählen, was es beim Gruppenmitglied unter deiner Maus tut; Rechtsklick lässt es ohne Aktion. Änderungen gelten außerhalb des Kampfes.",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta."] = "Klick auf eine: Alfas Karte springt dorthin. „Folgen“ setzt Pfeil und Route.",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta; la huella del grupo lo comparte con quien use Alfa."] = "Klick auf eine: Alfas Karte springt dorthin. „Folgen“ setzt Pfeil und Route; der Pfotenabdruck der Gruppe teilt sie mit allen, die Alfa nutzen.",
	["Clic en uno: el mapa va hasta él. Clic derecho en el mapa: uno nuevo."] = "Klick auf eine: Die Karte springt dorthin. Rechtsklick auf die Karte: eine neue.",
	["Clic para comprarla."] = "Klick, um ihn zu kaufen.",
	["Clic para desplegar."] = "Klick zum Ausklappen.",
	["Clic para elegir"] = "Klick zum Auswählen",
	["Clic para plegar o desplegar"] = "Klick zum Ein- oder Ausklappen",
	["Clic para plegar."] = "Klick zum Einklappen.",
	["Clic: abre %s."] = "Klick: öffnet %s.",
	["Clic: abre La Jauría."] = "Klick: öffnet La Jauría.",
	["Clic: abre su página con sus misiones, jefes y entrada."] = "Klick: öffnet seine Seite mit Quests, Bossen und Eingang.",
	["Clic: abrir o cerrar la ventana de Alfa"] = "Klick: Alfa-Fenster öffnen oder schließen",
	["Clic: elegir otra guía"] = "Klick: anderen Guide wählen",
	["Clic: elegir qué hace."] = "Klick: wählen, was es tut.",
	["Clic: elegir qué hace. Clic derecho: dejarla sin acción."] = "Klick: festlegen, was er tut. Rechtsklick: leer lassen.",
	["Clic: la flecha te lleva aquí."] = "Klick: Der Pfeil führt dich hierher.",
	["Clic: la flecha te lleva. Clic derecho: ya no mostrarla."] = "Klick: Der Pfeil führt dich hin. Rechtsklick: nicht mehr anzeigen.",
	["Clic: la lista de pasos. Rueda: mirar otros pasos sin cambiar nada."] = "Klick: die Schrittliste. Mausrad: andere Schritte ansehen, ohne etwas zu ändern.",
	["Clic: ocultarlo en el modelo."] = "Klick: am Modell ausblenden.",
	["Clic: opciones  ·  Mayús+clic: seguir"] = "Klick: Optionen  ·  Umschalt+Klick: folgen",
	["Clic: resalta lo que lleva."] = "Klick: hebt ihren Inhalt hervor.",
	["Clic: seguir con la flecha"] = "Klick: mit dem Pfeil folgen",
	["Clic: ver su diario en Alfa"] = "Klick: sein Kompendium in Alfa ansehen",
	["Clic: volver a ponerlo."] = "Klick: wieder anlegen.",
	["Clásico WoW"] = "Klassisches WoW",
	["Cobra tus %d misiones listas"] = "Löse deine %d fertigen Quests ein",
	["Cocina"] = "Kochkunst",
	["Cofre"] = "Truhe",
	["Cofres, baúles y almejas que se abren."] = "Truhen, Kisten und Muscheln, die sich öffnen lassen.",
	["Coleccionables"] = "Sammelobjekte",
	["Color"] = "Farbe",
	["Color de clase"] = "Klassenfarbe",
	["Colores de clase en los marcos"] = "Klassenfarben in den Rahmen",
	["Colores de clase en los marcos, un cuadro de información más útil, el probador mejorado, la siguiente parada en los vuelos y sin voces de error. Cada una se apaga abajo cuando quieras."] = "Klassenfarben in den Rahmen, ein nützlicherer Tooltip, die verbesserte Anprobe, der nächste Halt bei Flügen und keine Fehlerstimmen. Jede kannst du unten jederzeit ausschalten.",
	["Columnas"] = "Spalten",
	["Comando"] = "Befehl",
	["Comandos de Ruta:"] = "Befehle von Route:",
	["Combate"] = "Kampf",
	["Combate feral"] = "Wilder Kampf",
	["Combate feral para subir"] = "Wilder Kampf zum Leveln",
	["Combate para subir"] = "Kampf zum Leveln",
	["Comerciante"] = "Händler",
	["Comerciante:"] = "Händler:",
	["Comercio"] = "Handel",
	["Comida que da aguante o fuerza extra, y comes mientras descansas."] = "Essen, das zusätzliche Ausdauer oder Stärke gibt; du isst, während du dich ausruhst.",
	["Comisión de la subasta"] = "Auktionshaus-Anteil",
	["Comisión de la subasta estimada: %d%%."] = "Geschätzter Auktionshaus-Anteil: %d%%.",
	["Comodidades"] = "Komfort",
	["Comparar equipo con mi build"] = "Ausrüstung mit meinem Build vergleichen",
	["Comparte %s"] = "%s teilen",
	["Comparte tu rastro con la manada"] = "Teile deine Spur mit dem Rudel",
	["Comparte tu ubicación y ve a la manada"] = "Teile deinen Standort und sieh das Rudel",
	["Comparte tus talentos"] = "Teile deine Talente",
	["Compartes"] = "Du teilst",
	["Compartes tu ubicación"] = "Du teilst deinen Standort",
	["Compartes tu ubicación con La Jauría."] = "Du teilst deinen Standort mit La Jauría.",
	["Compartes tu ubicación con La Jauría. Lo cambias cuando quieras en /alfa manada."] = "Du teilst deinen Standort mit La Jauría. Ändere es jederzeit unter /alfa manada.",
	["Compartes tu ubicación: %s"] = "Du teilst deinen Standort: %s",
	["Compartido por %s"] = "Geteilt von %s",
	["Compartir"] = "Teilen",
	["Compartir con el grupo"] = "Mit der Gruppe teilen",
	["Compartir con la manada"] = "Mit dem Rudel teilen",
	["Compartir esta ruta"] = "Diese Route teilen",
	["Compartir mi ubicación"] = "Meinen Standort teilen",
	["Compartir mi ubicación con La Jauría"] = "Meinen Standort mit La Jauría teilen",
	["Compartir..."] = "Teilen...",
	["Compartiste %s con tu grupo."] = "Du hast %s mit deiner Gruppe geteilt.",
	["Compañeros por columna"] = "Mitglieder pro Spalte",
	["Completa el objetivo"] = "Schließ das Ziel ab",
	["Completa o entrega las que tienes abiertas"] = "Schließ die offenen ab oder gib sie ab",
	["Componentes"] = "Reagenzien",
	["Comprar"] = "Kaufen",
	["Comprar otra casilla del banco"] = "Weiteren Bankplatz kaufen",
	["Comprar por %s"] = "Für %s kaufen",
	["Comunidad"] = "Community",
	["Común"] = "Verbreitet",
	["Con 10 de furia o más lo lanzas."] = "Ab 10 Wut kannst du ihn wirken.",
	["Con aullido"] = "Mit Heulen",
	["Con dos armas pega más rápido: guarda maná para el final."] = "Mit zwei Waffen schlägt er schneller zu: Spar dir Mana für das Ende auf.",
	["Con el cuadro oculto en combate, mantén presionado Mayús para verlo."] = "Wenn der Tooltip im Kampf ausgeblendet ist, halte Umschalt gedrückt, um ihn zu sehen.",
	["Con el cursor encima no se cierra."] = "Solange der Cursor darauf ist, schließt er sich nicht.",
	["Con el entrenador más cercano en tu camino."] = "Mit dem nächsten Lehrer auf deinem Weg.",
	["Con ella lanzas la caña y, cuando pica, recoges el pez. Pulsa el botón y luego la tecla que quieras."] = "Damit wirfst du die Angel aus und holst den Fisch ein, wenn er anbeißt. Drück den Knopf und dann die gewünschte Taste.",
	["Con ella lanzas la caña y, cuando pica, recoges el pez. También está en el menú de atajos del juego, en Alfa."] = "Damit wirfst du die Angel aus und holst den Fisch ein, wenn er anbeißt. Sie steht auch in der Tastaturbelegung des Spiels, unter Alfa.",
	["Con la caña en el agua"] = "Angel im Wasser",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "Mit der Controller-Oberfläche öffnet sich die Spielkarte mit ihrer eigenen Taste.",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "Mit der Controller-Oberfläche überlässt Alfa die Taschen dem Spiel. Du kannst Alfas Fenster trotzdem von hier öffnen.",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "Mit Alfas Taschen siehst du alles in einem Fenster: drei Ansichten, Suche, deine Taschenleiste und was du verkaufen kannst, wenn sie voll werden.",
	["Con mando, se quedan las bolsas del juego"] = "Mit Controller bleiben die Taschen des Spiels",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "Mit oder ohne Umschalt, Strg oder Alt. Es wird nichts gewirkt: Hier siehst du, was auf dein Gruppenmitglied gewirkt würde.",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "Bei wenig Gesundheit ruft er zwei Helfer: Hat er nur noch wenig, erledigt ihn; sonst tötet zuerst die Helfer.",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "Bei wenig Gesundheit verwandelt er sich in eine Schlange und schlägt härter zu: Spar dir deine besten Angriffe für diesen Moment auf.",
	["Con reputación %s"] = "Ab Ruf %s",
	["Con sonido"] = "Mit Ton",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "Mit deinem Build weiß Alfa, welche Werte dir nützen und welche Ausrüstung du suchen solltest.",
	["Con tu punto libre se compra 1 rango de %s:"] = "Mit deinem freien Punkt kaufst du 1 Rang von %s:",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "Mit deinen %d freien Punkten werden %d Ränge von %s gekauft:",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "Mit einem Gegner im Ziel, vor Kampfbeginn, und durchsichtig, damit es nicht stört.",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "Er friert alle in seiner Nähe ein: Wenn du auf Distanz kämpfst, halte Abstand.",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "Friere das Monster mit Frostnova ein und geh auf Abstand, bevor du weiterzauberst.",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "Sie friert Spieler fest und wirkt Blitze: Wenn ihr auf Distanz kämpft, verteilt euch.",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "Du frierst Monster ein und verlangsamst sie, damit sie dich nie erreichen: der sicherste Magier zum Leveln.",
	["Conjúralas fuera de combate."] = "Zaubere sie außerhalb des Kampfes herbei.",
	["Conseguir %d de %s"] = "%d %s besorgen",
	["Conseguir %s"] = "%s besorgen",
	["Consejo en el cuadro de los objetos"] = "Tipp im Tooltip der Gegenstände",
	["Consejos"] = "Tipps",
	["Consejos de equipo apagados."] = "Ausrüstungsberatung ist aus.",
	["Consejos para jugarlo"] = "Tipps zum Spielen",
	["Conserva %s: vale más de otra forma."] = "Behalte %s: Anders ist es mehr wert.",
	["Considerar desencantar"] = "Entzaubern berücksichtigen",
	["Consigue %s"] = "Besorge %s",
	["Consumibles"] = "Verbrauchsgüter",
	["Contenta"] = "Zufrieden",
	["Contigo"] = "Bei dir",
	["Continuar"] = "Weiter",
	["Continuar mi ruta"] = "Meine Route fortsetzen",
	["Contra jefes de nivel alto fallas mucho: esto lo arregla."] = "Gegen hochstufige Bosse verfehlst du oft: Das behebt es.",
	["Contra jefes fallas mucho: esto te ayuda."] = "Gegen Bosse verfehlst du oft: Das hilft dir.",
	["Control de animación"] = "Animationssteuerung",
	["Coordenadas en el mapa"] = "Koordinaten auf der Karte",
	["Coordenadas en el minimapa"] = "Koordinaten auf der Minikarte",
	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "Kopiere diesen Text (Strg+C) und gib ihn an dein Rudel weiter. Sie fügen ihn unter „Importieren“ ein.",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "Kopiere die Zeichenkette unten und gib sie im Chat oder auf Discord weiter: Mit Alfa fügen sie sie unter „Importieren“ ein und haben denselben Build wie du.",
	["Copia tu mapa al clic para lanzar de Blizzard, así curas igual en sus marcos de grupo. Si el juego no lo deja, abre su ventana para que lo hagas ahí."] = "Kopiert deine Belegung in Blizzards Klickzauber, damit du in dessen Gruppenrahmen genauso heilst. Erlaubt das Spiel es nicht, öffnet sich dessen Fenster, damit du es dort machst.",
	["Copiar"] = "Kopieren",
	["Copiar el Discord"] = "Discord kopieren",
	["Coral"] = "Koralle",
	["Correr"] = "Laufen",
	["Crear %s ≈ %s"] = "%s herstellen ≈ %s",
	["Crear ruta"] = "Route erstellen",
	["Crecen hacia"] = "Wachsen nach",
	["Criaturas de nivel %d a %d"] = "Kreaturen der Stufe %d bis %d",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "Seltene Kreaturen und Schätze: wo sie erscheinen und was sie fallen lassen.",
	["Cristal"] = "Glas",
	["Crítico"] = "Kritisch",
	["Crítico con hechizos"] = "Zauberkrit",
	["Críticos enormes: matas antes de que te curen."] = "Riesige Krits: Du tötest, bevor sie geheilt werden.",
	["Críticos más fuertes."] = "Stärkere Krits.",
	["Críticos un poco más fuertes."] = "Etwas stärkere Krits.",
	["Ctrl"] = "Strg",
	["Cuadro de información"] = "Tooltip",
	["Cualquier criatura de su nivel"] = "Jede Kreatur seiner Stufe",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "Jede deiner Fähigkeiten, die das Spiel wegen eines Effekts hervorhebt.",
	["Cuando Alfa acepta y entrega misiones solo, puede limitarse a las que sirven a tu ruta."] = "Wenn Alfa Quests selbst annimmt und abgibt, kann es sich auf die beschränken, die deine Route braucht.",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "Wenn das Monster wenig Gesundheit hat, nutze Hinrichten (Alfa warnt dich).",
	["Cuando aprendas %s, también."] = "Sobald du %s lernst, auch diese.",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "Sobald du %s lernst, sagt es dir genau, wann du sie nutzen sollst.",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "Wenn du einen neuen Rang lernst, bietet dir ein Hinweis an, ihn in deinen Leisten zu tauschen.",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "Wenn du im Auktionshaus etwas suchst, merkt sich Alfa den niedrigsten Preis, den du siehst.",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "Wenn du ein Gasthaus oder eine Stadt betrittst und wenn dein Ruhebonus aufgebraucht ist.",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "Wenn seine Gesundheit sinkt, betäubt er alle und rennt zu seiner Truhe, um die Waffe zu wechseln: Wartet auf ihn, verfolgt ihn nicht.",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "Wenn du etwas trägst, sagt dir Alfa, ob du es beim Händler verkaufen, versteigern oder verarbeiten solltest, und wie viel du verdienst.",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "Wenn ein anderer Wolf mit Alfa seinen Standort teilt, erscheint er hier und auf deiner Karte. Damit das Rudel wächst, lade deine Freunde ein: Sie installieren Alfa, stimmen dem Teilen zu und treten dem Discord von La Jauría bei.",
	["Cuando se llenan"] = "Wenn sie voll werden",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "Wenn dir das Mana ausgeht, wechsle in die Katzengestalt, um den Kampf zu beenden.",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "Wenn du oder deine Gruppe kämpft, siehst du hier, wer den meisten Schaden macht.",
	["Cuando una pieza baja de este porcentaje."] = "Wenn ein Teil unter diesen Prozentsatz fällt.",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "Sobald du deinen ersten Boss besiegst, erscheint hier dein Fortschritt.",
	["Cuando ya casi se rompe."] = "Wenn es fast kaputt ist.",
	["Cuello"] = "Hals",
	["Cuenta:"] = "Account:",
	["Cuero"] = "Leder",
	["Cuerpo a cuerpo con tótems y golpes elementales: el chamán que mejor sube."] = "Nahkampf mit Totems und Elementarschlägen: der Schamane, der am besten levelt.",
	["Cuesta %s (tienes %s). Es la casilla %d de %d: después pon una bolsa en ella para guardar más."] = "Er kostet %s (du hast %s). Es ist Platz %d von %d: Steck danach eine Tasche hinein, um mehr zu lagern.",
	["Cuesta %s."] = "Kostet %s.",
	["Cuestan %s: te alcanza."] = "Sie kosten %s: Das reicht.",
	["Cuestan %s; llevas %s."] = "Sie kosten %s; du hast %s.",
	["Cuidado con atraer varios a la vez: Fuego no tiene tanto control."] = "Vorsicht beim Ziehen mehrerer Gegner: Feuer hat nicht so viel Kontrolle.",
	["Cura"] = "Heiler",
	["Cura a quien tenga el dolor de sombras; la pelea es corta."] = "Heile alle, die den Schattenschmerz haben; der Kampf ist kurz.",
	["Cura a sus ayudantes y a sí misma: interrúmpanla."] = "Sie heilt ihre Helfer und sich selbst: Unterbrecht sie.",
	["Cura a tu grupo con un clic."] = "Heil deine Gruppe mit einem Klick.",
	["Curación"] = "Heilung",
	["Curación con clic"] = "Heilen per Klick",
	["Curación: arrastra para mover"] = "Heilung: zum Verschieben ziehen",
	["Curandero"] = "Heiler",
	["Curas que van llegando"] = "Eingehende Heilung",
	["Cursor"] = "Cursor",
	["Cuándo"] = "Wann",
	["Cuántas casillas caben en cada fila."] = "Wie viele Plätze in jede Reihe passen.",
	["Cuántas casillas libres quedan cuando Alfa te avisa."] = "Wie viele freie Plätze übrig sind, wenn Alfa dich warnt.",
	["Cuántas habilidades después"] = "Wie viele Fähigkeiten danach",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "Wie viel Schaden jeder Block abfängt; erhöht auch den Schaden von Schildschlag.",
	["Cuánto dura un aviso en pantalla"] = "Wie lange ein Hinweis auf dem Bildschirm bleibt",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "Wie lange es bis zu deinem nächsten automatischen Schlag dauert, für jede Hand. Hilft dir, Zerschmettern oder Heldenhafter Stoß einzubauen, ohne Schläge zu verlieren.",
	["Cuántos en el top"] = "Wie viele im Top",
	["Cuántos se anuncian"] = "Wie viele angesagt werden",
	["Cuántos tienes, en el cuadro de cada objeto"] = "Wie viele du hast, im Tooltip jedes Gegenstands",
	["Cuántos van en cada columna (o fila) antes de empezar otra. 5 es un grupo por columna."] = "Wie viele in jede Spalte (oder Reihe) kommen, bevor eine neue beginnt. 5 ist eine Gruppe pro Spalte.",
	["Cuéntanos qué te parece en La Jauría."] = "Sag uns bei La Jauría, wie du es findest.",
	["Cámara"] = "Kamera",
	["Cómo conseguir cualquier objeto, misión o PNJ, y qué guía te lleva ahí."] = "Wie du jeden Gegenstand, jede Quest und jeden NPC bekommst und welcher Guide dich hinführt.",
	["Cómo conseguir cualquier objeto, montura, PNJ, misión o lugar."] = "Wie du an jeden Gegenstand, jedes Reittier, jeden NPC, jede Quest oder jeden Ort kommst.",
	["Cómo conseguirlo"] = "So bekommst du es",
	["Cómo decide Alfa"] = "Wie Alfa entscheidet",
	["Cómo juego"] = "Wie ich spiele",
	["Cómo se usa"] = "So geht's",
	["Cómo se ven las zonas sin descubrir"] = "Wie unentdeckte Gebiete aussehen",
	["Cómo trabaja tu ruta"] = "So funktioniert deine Route",
	["Cómprala con un vendedor."] = "Kauf sie bei einem Händler.",
	["DPS"] = "DPS",
	["DPS del arma"] = "Waffen-DPS",
	["Daga"] = "Dolch",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Füttere dein Tier, damit es zufrieden ist und härter zuschlägt.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Füttere es, damit es glücklich ist: Dann schlägt es härter zu.",
	["Datos"] = "Daten",
	["Daño"] = "Schaden",
	["Daño a distancia"] = "Fernkampfschaden",
	["Daño con el tiempo: ponla al empezar la pelea."] = "Schaden über Zeit: Zu Kampfbeginn wirken.",
	["Daño de arcos, armas de fuego y ballestas."] = "Schaden von Bögen, Schusswaffen und Armbrüsten.",
	["Daño de fuego con el tiempo."] = "Feuerschaden über Zeit.",
	["Daño del arma"] = "Waffenschaden",
	["Daño directo de fuego y sombras: matas antes de que el monstruo llegue."] = "Direkter Feuer- und Schattenschaden: Du tötest, bevor das Monster ankommt.",
	["Daño directo de tus armas y habilidades."] = "Direkter Schaden deiner Waffen und Fähigkeiten.",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "Schaden in einer Fünfergruppe: hart zuschlagen, ohne dem Tank die Monster zu stehlen.",
	["Daño extra después de recibir críticos."] = "Extraschaden, nachdem du Krits erlitten hast.",
	["Daño extra después de recibir un golpe crítico."] = "Extraschaden, nachdem du einen kritischen Treffer erlitten hast.",
	["Daño por segundo"] = "Schaden pro Sekunde",
	["De Forever"] = "Forever",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono; las de área, solo con 3 o más enemigos peleando."] = "Von oben nach unten: Die erste, die das Spiel dich nutzen lässt, erscheint im Symbol; Flächenfähigkeiten nur bei 3 oder mehr kämpfenden Gegnern.",
	["De la base de datos incluida"] = "Aus der mitgelieferten Datenbank",
	["De la otra facción"] = "Andere Fraktion",
	["De misión"] = "Questgegenstände",
	["De nivel %.1f a %.1f, con unos %s de oro. Solo misiones que ya puedes tomar; lo que pide más nivel va después de un paso que lo espera."] = "Von Stufe %.1f auf %.1f, mit etwa %s Gold. Nur Quests, die du schon annehmen kannst; was eine höhere Stufe braucht, kommt nach einem Schritt, der darauf wartet.",
	["Debajo del ícono: útil mientras aprendes."] = "Unter dem Symbol: nützlich, solange du lernst.",
	["Dedo"] = "Finger",
	["Defensa"] = "Verteidigung",
	["Deja que el tanque golpee primero unos segundos antes de usar tus golpes fuertes."] = "Lass den Tank ein paar Sekunden zuerst zuschlagen, bevor du deine starken Schläge nutzt.",
	["Deja que tu mascota empiece la pelea y dispara cuando el monstruo la esté atacando."] = "Lass dein Tier den Kampf beginnen und schieß, wenn das Monster es angreift.",
	["Deja solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Lässt nur das Wesentliche: dich, deine Gruppe, deine Markierungen und den nächsten Schritt des Guides.",
	["Dejar"] = "Beenden",
	["Dejar de seguir"] = "Nicht mehr folgen",
	["Dejarlo como recomienda Alfa"] = "So einstellen, wie Alfa es empfiehlt",
	["Del motor de Alfa: al subir de nivel te muestra qué aprender y cuánto cuesta."] = "Aus Alfas Kern: Beim Stufenaufstieg zeigt er dir, was du lernen kannst und was es kostet.",
	["Del motor de Alfa: con el entrenador más cercano en tu camino."] = "Aus Alfas Kern: mit dem nächsten Lehrer auf deinem Weg.",
	["Del preajuste"] = "Aus der Voreinstellung",
	["Demonología"] = "Dämonologie",
	["Demonología para subir"] = "Dämonologie zum Leveln",
	["Dentro"] = "Drinnen",
	["Dentro de"] = "Enthalten in",
	["Dentro de la mazmorra"] = "Im Dungeon",
	["Dentro de mazmorras y ciudades no hay nodos. Sal al mundo y tu ruta se arma en un clic."] = "In Dungeons und Städten gibt es keine Vorkommen. Geh hinaus in die Welt, dann ist deine Route einen Klick entfernt.",
	["Dentro de una instancia el juego no deja compartir: sale solo cuando salgas."] = "In einer Instanz lässt das Spiel kein Teilen zu: Es wird von selbst gesendet, wenn du sie verlässt.",
	["Dentro de una instancia no se puede seguir a nadie."] = "In einer Instanz kannst du niemandem folgen.",
	["Depositar"] = "Einlagern",
	["Depositar rápido"] = "Schnell einlagern",
	["Depósito detenido: guardaste %d."] = "Einlagern gestoppt: %d eingelagert.",
	["Derecho"] = "Rechts",
	["Derrota a %s"] = "Besiege %s",
	["Desarmar más seguido: quitas el arma a los enemigos que pegan fuerte."] = "Öfter entwaffnen: Du nimmst hart zuschlagenden Gegnern die Waffe ab.",
	["Desbloquear %s"] = "%s freischalten",
	["Descansa en una posada o una ciudad para juntar más."] = "Ruh dich in einem Gasthaus oder einer Stadt aus, um mehr Ruhebonus zu sammeln.",
	["Descansando%s%d%% de un nivel"] = "Du erholst dich%s%d%% einer Stufe",
	["Descansando: %d %%"] = "Erholung: %d %%",
	["Descanso"] = "Erholung",
	["Descanso %d %%"] = "Ruhebonus %d %%",
	["Desconectado"] = "Offline",
	["Descontenta"] = "Unglücklich",
	["Descubriste a %s"] = "Du hast %s entdeckt",
	["Descubriste a %s (%s)."] = "Du hast %s entdeckt (%s).",
	["Desde cero"] = "Von Grund auf",
	["Desde cuántas habilidades"] = "Ab wie vielen Fähigkeiten",
	["Desde el nivel 10"] = "Ab Stufe 10",
	["Desde el nivel 20"] = "Ab Stufe 20",
	["Desde nivel %d"] = "Ab Stufe %d",
	["Desencantar ≈ %s"] = "Entzaubern ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "Entzaubern: ≈ %s pro Gegenstand%s. Benötigt Verzauberkunst %d.",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "Verwunden macht mehr Schaden, solange das Monster blutet; du brauchst es für Tiefe Wunden.",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "Verwunden macht mehr Schaden; du brauchst es für Tiefe Wunden.",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "Verwunden bereitet mehr Überwältigen vor: mehr Schläge, denen man nicht ausweichen kann.",
	["Deshacer"] = "Rückgängig",
	["Desmarcar"] = "Markierung aufheben",
	["Después"] = "Später",
	["Después de cada golpe, regresa a tu lugar rápido."] = "Kehr nach jedem Schlag schnell an deinen Platz zurück.",
	["Después de estos siguen %d más."] = "Danach folgen noch %d weitere.",
	["Después de otra"] = "Nach einer anderen",
	["Después de tu segunda pelea, aquí ves la de antes."] = "Nach deinem zweiten Kampf siehst du hier den vorherigen.",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "Nach einem Krit greifst du schneller an: mehr Schläge, mehr Wut.",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "Danach entzündet ihr die Kohlenbecken am Altar, und Wellen von Gegnern kommen: Bereitet euch vorher vor.",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "Nach dem ersten Boss öffnet ein Gefangener deiner Fraktion die Tür: Sprich mit ihm.",
	["Después sigue"] = "Danach folgt",
	["Después: %d %% del nivel %d"] = "Danach: %d %% von Stufe %d",
	["Después: nivel %d"] = "Danach: Stufe %d",
	["Destino"] = "Ziel",
	["Destrucción"] = "Zerstörung",
	["Destrucción para subir"] = "Zerstörung zum Leveln",
	["Desuellas lo que matas y lo conviertes en armaduras de cuero para ti; lo que sobra se vende."] = "Du häutest, was du tötest, und machst daraus Lederrüstung für dich; der Rest lässt sich verkaufen.",
	["Desuello"] = "Kürschnerei",
	["Desvías golpes con tu arma."] = "Du lenkst Schläge mit deiner Waffe ab.",
	["Detalle al pasar el ratón"] = "Details beim Darüberfahren",
	["Detalle fino de cada zona"] = "Feine Details jedes Gebiets",
	["Detener"] = "Stopp",
	["Detener (%d/%d)"] = "Stopp (%d/%d)",
	["Devolver los avisos a su lugar"] = "Hinweise an ihren Platz zurücksetzen",
	["Diario"] = "Tagebuch",
	["Diario de mazmorras"] = "Dungeonkompendium",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "Zeichnet die vollständige Grafik jedes Gebiets, auf seine Form zugeschnitten, mit den mitgelieferten Detailtexturen. Ohne sie ist die Karte trotzdem vollständig, nur weicher zwischen den Gebieten.",
	["Dinero de toda la cuenta"] = "Gold des ganzen Accounts",
	["Dinero de tus personajes"] = "Gold deiner Charaktere",
	["Disciplina"] = "Disziplin",
	["Disciplina para subir"] = "Disziplin zum Leveln",
	["Dispara desde lejos: alguien debe ir por él."] = "Er schießt aus der Ferne: Jemand muss zu ihm hin.",
	["Disparo apuntado: tu disparo más fuerte."] = "Gezielter Schuss: dein stärkster Schuss.",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "Arkaner Schuss: spontan, nutze ihn, sobald er bereit ist.",
	["Disponible a nivel %d"] = "Verfügbar ab Stufe %d",
	["Doble clic derecho"] = "Doppel-Rechtsklick",
	["Doble clic derecho para lanzar"] = "Doppel-Rechtsklick zum Auswerfen",
	["Doble clic mientras pescas vuelve a lanzar"] = "Doppelklick beim Angeln wirft erneut aus",
	["Dominio de bestias"] = "Tierherrschaft",
	["Dominio de bestias para subir"] = "Tierherrschaft zum Leveln",
	["Dormir"] = "Schlafen",
	["Dos armas"] = "Zwei Waffen",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "Zwei Waffen und viel Wut. Furor trifft mit guter Ausrüstung härter als Waffen, und Blutdurst kommt auf Stufe 40. Ab Stufe 20 brauchst du zwei Einhandwaffen.",
	["Dos clics y Alfa te lleva"] = "Zwei Klicks, und Alfa bringt dich hin",
	["Dos manos"] = "Zweihändig",
	["Dos monstruos a la vez dejan de ser un problema."] = "Zwei Monster auf einmal sind kein Problem mehr.",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "Zwei Sammelberufe: stetiges Gold ohne Zeitverlust, genau dann, wenn du es am meisten brauchst.",
	["Drenar alma al rematar te da uno."] = "Seelendieb beim Todesstoß gibt dir einen.",
	["Druida"] = "Druide",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "Er schläfert einen Spieler ein und wirkt Schattenzauber: Unterbrich ihn.",
	["Duplicar"] = "Duplizieren",
	["Durabilidad"] = "Haltbarkeit",
	["Duración"] = "Dauer",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "Im Kampf weckt er Steinwächter: Jemand muss sie tanken, oder tötet sie schnell.",
	["Dónde"] = "Wo",
	["Dónde entregar"] = "Wo abgeben",
	["Dónde está"] = "Wo es ist",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "Wo jeder ist, was er verkauft, was er fallen lässt und seine Quests.",
	["Dónde se entrega"] = "Wo man sie abgibt",
	["Dónde se ven"] = "Wo sie erscheinen",
	["Ejecutar cuesta menos ira: rematas antes."] = "Hinrichten kostet weniger Wut: Du erledigst sie früher.",
	["Ejecutar más barato para rematar jefes."] = "Günstigeres Hinrichten, um Bosse zu erledigen.",
	["El Discord de La Jauría"] = "Der Discord von La Jauría",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "Ausdauer ist dein bester Freund: mehr Gesundheit für mehr Aderlass.",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "Die Waffe in der Waffenhand sollte die langsamste und stärkste sein, die in der Schildhand die schnellste.",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "Die Bank ist voll: Kauf einen weiteren Platz oder steck eine größere Tasche in die Bank.",
	["El bonus de tu arma al máximo."] = "Der Bonus deiner Waffe auf dem Maximum.",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "Der Rand nimmt die Farbe des Schwächungszaubers an (Magie, Fluch, Krankheit oder Gift), wenn du ihn entfernen kannst.",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "Der Knopf „Mit Alfa scannen“ unter dem Auktionshausfenster.",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "„Nachschlagen“ im Kern ist aus (Einstellungen > Entdecken): Schalte es ein, damit Alfa Guides erstellen kann.",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "Der Weg zum Ziel auf der Weltkarte und der Minikarte: eine Linie oder Punkte, wo du läufst, Linien, wo du fliegst, segelst oder reitest, und die folgenden Etappen blasser.",
	["El camino hasta el destino dibujado en el mapa."] = "Der Weg zum Ziel, auf die Karte gezeichnet.",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "Der einfachste Weg zum Leveln: eine große Waffe, Schläge, die bluten lassen, und Tödlicher Stoß auf Stufe 40. Du hältst viel aus und tötest schnell.",
	["El clan"] = "Der Clan",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "Ein einfacher Rechtsklick zoomt die Spielkarte weiterhin heraus, wie immer.",
	["El clic izquierdo solo selecciona"] = "Linksklick wählt nur als Ziel",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "Der Klassiker für den Kampf gegen Spieler: Tödlicher Stoß kürzt die Heilung des Gegners, Verbesserte Kniesehne hält ihn fest und Verbesserter Sturmangriff gibt dir Wut zum Start.",
	["El color de mi clase"] = "Meine Klassenfarbe",
	["El comerciante no lo compra"] = "Händler kaufen es nicht",
	["El corcho está en el agua. Cuando se hunda, haz clic derecho sobre él para recoger."] = "Der Schwimmer ist im Wasser. Wenn er abtaucht, klick ihn mit rechts an, um einzuholen.",
	["El corcho está en el agua. Cuando se hunda, pulsa %s para recoger."] = "Der Schwimmer ist im Wasser. Wenn er abtaucht, drück %s, um einzuholen.",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "Der Tooltip des Spielers beim Darüberfahren. Im Kampf erscheint er nicht, damit er nicht stört.",
	["El daño por segundo de tu arma a distancia."] = "Der Schaden pro Sekunde deiner Fernkampfwaffe.",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "Der Schaden pro Sekunde der Waffe: für den Krieger das Wichtigste beim Leveln.",
	["El destino de la flecha y sus zonas en el minimapa."] = "Das Ziel des Pfeils und seine Bereiche auf der Minikarte.",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "Das Ziel des Pfeils, der Weg dorthin und die anderen Ziele des Schritts, auf der Karte.",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "Das Dungeonkompendium des Kerns ist aus (Einstellungen > Entdecken > Dungeons).",
	["El diario de mazmorras está apagado"] = "Das Dungeonkompendium ist aus",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "Der Gegner ist ausgewichen: Überwältigen kann man nicht ausweichen, und es trifft hart.",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "Der Gegner ist ausgewichen: Dieser Nahkampfschlag ist bereit.",
	["El enemigo esquivó: este golpe está listo."] = "Der Gegner ist ausgewichen: Dieser Schlag ist bereit.",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "Der Gegner ist direkt bei dir: Schlag ihn im Nahkampf.",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "Willenskraft gibt dir Mana schnell zurück: Du musst kaum rasten.",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "Das Feuer trifft alle in der Nähe: Halte die Gesundheit der Nahkämpfer hoch.",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "Der Krieger mit dem meisten Schaden in Dungeons. Mit einem Tank vorne stehen deine zwei Waffen nie still, und Verbessertes Hinrichten erledigt die Bosse.",
	["El izquierdo selecciona y el derecho abre el menú."] = "Links visiert an und rechts öffnet das Menü.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "Links visiert an und rechts öffnet das Menü. Den Rest wählst du.",
	["El izquierdo selecciona y el derecho abre el menú; tu clase no tiene buffs para otros."] = "Links visiert an und rechts öffnet das Menü; deine Klasse hat keine Buffs für andere.",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "Das Spiel wählt je nach Lage zwischen diesen; das Symbol zeigt dir, welche jetzt am besten ist.",
	["El juego la hizo brillar: es buen momento para usarla."] = "Das Spiel hat sie aufleuchten lassen: ein guter Moment, sie zu nutzen.",
	["El juego no aceptó esa tecla."] = "Das Spiel hat diese Taste nicht angenommen.",
	["El juego no aceptó la prueba."] = "Das Spiel hat den Test nicht angenommen.",
	["El juego no deja cambiar talentos ahora mismo"] = "Das Spiel erlaubt gerade keine Talentänderung",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "Das Spiel erlaubt gerade keine Nachrichten (eine Begegnung oder ein Match). Deine Spur wird danach wieder von selbst gesendet.",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "Das Spiel lässt Testaccounts keine Addon-Nachrichten senden und keine eigenen Kanäle nutzen. Deine Gruppe siehst du trotzdem.",
	["El juego no dejó cambiar las demás."] = "Das Spiel hat das Ändern der übrigen nicht erlaubt.",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "Das Spiel hat das Teilen der Markierung gerade nicht erlaubt. Versuch es gleich noch mal.",
	["El juego no dejó comprar ese rango."] = "Das Spiel hat den Kauf dieses Rangs nicht erlaubt.",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "Das Spiel hat uns nicht in Alfas versteckten Kanal gelassen, und ohne Gilde gibt es keinen anderen Weg zu teilen. Alfa versucht es in ein paar Minuten von selbst erneut. Deine Gruppe siehst du trotzdem.",
	["El juego no la ofrece ahora mismo."] = "Das Spiel bietet sie gerade nicht an.",
	["El juego no lo dice ahora."] = "Das Spiel verrät es gerade nicht.",
	["El juego no permite usar el medidor ahora."] = "Das Spiel erlaubt den Schadensmesser gerade nicht.",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "Das Spiel hat keinen Kampfassistenten von Blizzard, also schlägt Alfa mit seiner eigenen Priorität für %s vor und liest dabei nur deinen Charakter: deine Ressource, deine Effekte und was das Spiel dich nutzen lässt. Bei 3 oder mehr Gegnern wechselt es zu Flächenfähigkeiten. Du entscheidest, was du drückst.",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "Das Spiel verbirgt die genauen Zahlen, während du kämpfst: Balken und Wert siehst du, die Details nach dem Kampf.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "Das Spiel hat die Bestätigung der Änderungen abgelehnt. Sie wurden rückgängig gemacht, damit dein Baum bleibt, wie er war.",
	["El juego todavía no carga tu árbol"] = "Das Spiel hat deinen Baum noch nicht geladen",
	["El juego todavía no carga tu árbol."] = "Das Spiel hat deinen Baum noch nicht geladen.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "Das Spiel hat deine Talente noch nicht geladen. Warte ein paar Sekunden oder öffne einmal das Talentfenster (Taste N).",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "Das Spiel hat die Daten einiger Gegenstände noch nicht. Gleich erscheinen sie.",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "Das Spiel verbirgt die Zahlen oder Namen noch (das passiert im Kampf und in Dungeons). Versuch es danach noch mal.",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "Der Magier mit dem meisten Schaden: Feuerzauber und Krits, die brennen.",
	["El mapa a tu gusto"] = "Die Karte nach deinem Geschmack",
	["El mapa de Alfa"] = "Alfas Karte",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Alfas Karte, die des Spiels und die Minikarte. Wenn dich etwas stört, schalte es hier aus; die anderen Module von Alfa fügen ihre Ebenen zu derselben Liste hinzu.",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "Die ganze Welt auf einer Karte mit Zoom, deinen Markierungen und einer einzigen Steuerung für alles, was darauf gezeichnet wird.",
	["El mapa no se abre en combate."] = "Die Karte öffnet sich nicht im Kampf.",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "Das Medaillon unter jeder Markierung auf Karte und Minikarte: das von Alfa oder nur das Symbol, ohne Medaillon.",
	["El medidor no está disponible"] = "Der Schadensmesser ist nicht verfügbar",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "Das Lupenmenü der Spielkarte enthält auch alle Ebenen von Alfa.",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "Die Minikarte wird von rund zu eckig, mit dünnem Rand. Nicht empfohlen zusammen mit drehender Minikarte.",
	["El modelo no lleva nada aquí."] = "Das Modell trägt hier nichts.",
	["El modo prueba se usa fuera de combate."] = "Der Testmodus geht nur außerhalb des Kampfes.",
	["El motor no aceptó la guía."] = "Der Kern hat den Guide nicht angenommen.",
	["El motor no puede armar guías ahora."] = "Der Kern kann gerade keine Guides erstellen.",
	["El mundo entero en un mapa"] = "Die ganze Welt auf einer Karte",
	["El módulo Curación no está cargado."] = "Das Modul Heilung ist nicht geladen.",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Der Name jedes Gebiets auf Alfas Karte.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "Die Zahl unten links an jedem Ausrüstungsteil.",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "Die Zahl ist die Reihenfolge, in der es genommen wird. Fahr mit der Maus über ein Talent, um zu sehen, was es tut.",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "Der Gegenstand, den der aktuelle Schritt benutzt, oder der Questgegenstand, den er sammelt, leuchtet in deinen Taschen. Ein Gegenstand, den ein späterer Schritt braucht, bekommt ein Schloss, damit du ihn nicht verkaufst.",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "Die Reihenfolge zählt mehr als die Zahlen: Such Teile mit den ersten Werten der Liste.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Alfas Datenpaket (Alfa_Codex) ist deaktiviert: Aktiviere es in der Addon-Liste und lade neu.",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "Der einfachste Schurke zum Leveln: Er schlägt von vorne zu, weicht viel aus und hält mehr aus als die anderen.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "Der Stufenbereich jedes Gebiets, eingefärbt nach deiner Stufe.",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "Der Tracker sagt dir den nächsten Schritt, und der Pfeil führt dich hin.",
	["El registro de daño del juego está apagado"] = "Die Schadensaufzeichnung des Spiels ist aus",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "Die Schadensaufzeichnung des Spiels ist aus: Schalte sie ein, um das Top deiner Gruppe zu sehen.",
	["El reino limita los mensajes de addon salientes: %s"] = "Der Realm begrenzt ausgehende Addon-Nachrichten: %s",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "Der Heiler der Schamanen: Kettenheilungen und Totems, die der ganzen Gruppe helfen.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "Der Heiler der Druiden: Du heilst jede Gruppe und überlebst gut, auch wenn du solo langsam tötest.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "Der Heiler der Paladine: starke Heilungen und viel Rüstung, ideal für Gruppen.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "Der reine Heiler: große Heilungen und Heilungen für die ganze Gruppe.",
	["El sistema de equipo de Alfa no está disponible."] = "Alfas Ausrüstungssystem ist nicht verfügbar.",
	["El talento que toca"] = "Dein nächstes Talent",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "Der klassische Tank: Du blockst viel, erzeugst Bedrohung mit Rache und Schildschlag und hast Letztes Gefecht für den Fall, dass alles schiefgeht.",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "Der am schwersten zu tötende Tank: alle Verteidigungstalente, Verbesserter Schildwall und früh Letztes Gefecht. Perfekt, um mit dem Tanken anzufangen.",
	["El texto es demasiado largo."] = "Der Text ist zu lang.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "Der Text kam gekürzt oder verändert an: Kopiere ihn erneut.",
	["El tipo de nodos que une la ruta."] = "Die Art der Vorkommen, die die Route verbindet.",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "Der Ton der Hintergründe: Graphit ist der von Alfa, Nacht der dunkelste und Schiefer ein neutrales Grau.",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "Das DPS-Top deiner Gruppe oder deines Schlachtzugs in einem kleinen Fenster, mit dem aktuellen und dem vorherigen Kampf.",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Alfas Routenbaum, Quests, sobald sie freigeschaltet werden, und ein Gegenstandskatalog.",
	["El último punto: paras un poco más."] = "Der letzte Punkt: Du parierst etwas mehr.",
	["Elegido"] = "Gewählt",
	["Elegido por ti"] = "Von dir gewählt",
	["Elegir capas"] = "Ebenen wählen",
	["Elegir la siguiente guía"] = "Nächsten Guide wählen",
	["Elegir mi camino"] = "Meinen Weg wählen",
	["Elegir mi primera guía"] = "Meinen ersten Guide wählen",
	["Elegir mi tecla"] = "Meine Taste wählen",
	["Elegir otra guía"] = "Anderen Guide wählen",
	["Elegir qué sigue"] = "Wählen, was als Nächstes kommt",
	["Elegir una guía"] = "Guide wählen",
	["Elemental"] = "Elementar",
	["Elemental para subir"] = "Elementar zum Leveln",
	["Elfos de la noche"] = "Nachtelfen",
	["Elige algo de la lista"] = "Wähle etwas aus der Liste",
	["Elige el objeto"] = "Wähle den Gegenstand",
	["Elige el objeto en la Enciclopedia."] = "Wähle den Gegenstand in der Enzyklopädie.",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "Wähle, was du einlagerst: was du schon in der Bank hast, die Materialien, eine Kategorie oder alles außer Ausrüstung. Alles wird auf einmal verschoben, außerhalb des Kampfes.",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "Wähle, was du tun willst, und Alfa führt dich Schritt für Schritt.",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "Wähle, was die Karte zeigt: Guide, Quests, Rares, Reisen, Gebiete und was andere Module hinzufügen.",
	["Elige solo misiones que ya puedes tomar."] = "Es wählt nur Quests, die du schon annehmen kannst.",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "Wähle deinen Weg. Wenn du unsicher bist, fang mit dem Leveln an: Alfa sagt dir, was sich lohnt.",
	["Elige tu estilo"] = "Wähle deinen Stil",
	["Elige tu tecla para pescar"] = "Wähle deine Angeltaste",
	["Elige tus clics"] = "Wähle deine Klicks",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "Wähle deine Klicks, platziere deine Rahmen und teste sie. Das dauert eine Minute.",
	["Elige tú la zona."] = "Du wählst das Gebiet.",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "Wähle einen Weg: Alfa erstellt deinen Plan und führt dich Schritt für Schritt.",
	["Elige una guía para empezar"] = "Wähle einen Guide, um zu beginnen",
	["Elige uno y lo ves al instante en todas las ventanas de Alfa, también la flecha."] = "Wähle einen und sieh ihn sofort in allen Alfa-Fenstern, auch beim Pfeil.",
	["Eliges una"] = "Du wählst eine",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "Sie schläfert die ganze Gruppe ein und belebt dann Mograine wieder: Das ist normal, keine Panik.",
	["Embate con escudo: mucho daño y amenaza."] = "Schildschlag: viel Schaden und Bedrohung.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "Zerschmettern setzt deinen Angriff nicht mehr zurück: ein Extraschlag zwischen zwei Schlägen.",
	["Embate sin perder tu ataque automático."] = "Zerschmettern, ohne deinen automatischen Angriff zu verlieren.",
	["Embate sin perder tu ataque."] = "Zerschmettern, ohne deinen Schlag zu verlieren.",
	["Embate sin perder tu golpe automático."] = "Zerschmettern, ohne deinen automatischen Schlag zu verlieren.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "Zerschmettern, ohne deinen Angriff zurückzusetzen: ein Extraschlag.",
	["Embate: un golpe fuerte entre golpe y golpe."] = "Zerschmettern: ein starker Schlag zwischen zwei Schwüngen.",
	["Empezar"] = "Los geht's",
	["Empezar de cero"] = "Von vorn beginnen",
	["Empezar de nuevo"] = "Neu anfangen",
	["Empezó %s"] = "Begonnen %s",
	["Empezó %s."] = "Begonnen: %s.",
	["Empieza al usar este objeto"] = "Beginnt, wenn du diesen Gegenstand benutzt",
	["Empieza aquí"] = "Hier anfangen",
	["Empieza con %s, que se consigue en la mazmorra."] = "Sie beginnt mit %s, das man im Dungeon findet.",
	["Empieza con %s, que suelta %s."] = "Sie beginnt mit %s, das %s fallen lässt.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "Beginne aus der Ferne mit deinem langsamsten Zauber und beende mit den Spontanzaubern.",
	["Empieza dentro"] = "Beginnt drinnen",
	["Empieza una misión"] = "Startet eine Quest",
	["Empiezas: nivel %d"] = "Du startest: Stufe %d",
	["En 9 idiomas"] = "In 9 Sprachen",
	["En camino"] = "Unterwegs",
	["En combate"] = "Im Kampf",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "Im Kampf verbirgt das Spiel die genauen Zahlen: Balken und Werte siehst du trotzdem, Details und Ansage nach dem Kampf.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "Im Kampf öffnet sich die Spielkarte nicht über Alfa: Nutze die von Alfa.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "Im Kampf erscheint der Tooltip von Charakteren und Kreaturen in der Welt nicht (der der Rahmen schon).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "Im Kampf gibt es keinen Test: Verlass den Kampf und komm zu diesem Schritt zurück.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "Im Kampf zeigt das Symbol die Fähigkeit, die Blizzards Kampfassistent vorschlägt, und die %d folgenden. Du entscheidest, was du drückst: Alfa drückt nie etwas für dich.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "Im Kampf zeigt das Symbol die Fähigkeit, die Blizzards Kampfassistent vorschlägt. Du entscheidest, was du drückst: Alfa drückt nie etwas für dich.",
	["En combate: espera a terminar"] = "Im Kampf: Warte, bis er vorbei ist",
	["En curso"] = "Läuft",
	["En el camino"] = "Auf dem Weg",
	["En el chat"] = "Im Chat",
	["En el juego"] = "Im Spiel",
	["En el mapa"] = "Auf der Karte",
	["En el mapa del mundo"] = "Auf der Weltkarte",
	["En el marco del objetivo"] = "Auf dem Zielrahmen",
	["En el minimapa"] = "Auf der Minikarte",
	["En el mundo"] = "In der Welt",
	["En el nivel 10 domas tu bestia."] = "Auf Stufe 10 zähmst du dein Tier.",
	["En el nivel 20 aprendes venenos."] = "Auf Stufe 20 lernst du Gifte.",
	["En esta zona"] = "In diesem Gebiet",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "In der Gruppe gibt es fast immer mehrere Gegner: Du triffst zwei gleichzeitig.",
	["En grupo, cura al tanque antes que a nadie."] = "Heile in der Gruppe den Tank vor allen anderen.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "Heile in der Gruppe zuerst den Tank und zieh selbst keine Monster.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "Heile in der Gruppe, bevor die Gesundheit stark sinkt: Das ist günstiger.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "Stell in der Gruppe deine Mana- und Heiltotems nahe der Gruppe auf.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "In der Schiffshöhle sind viele Piraten: Springt nicht alle auf einmal zum Steg hinunter.",
	["En la pelea, el juego te avisa"] = "Im Kampf warnt dich das Spiel",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Tötet sie im zweiten Teil zuerst: Sie heilt viel.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "Beim Auktionshaus zählt der niedrigste gesehene Preis abzüglich des Anteils (%d%%, geschätzt). Beim Entzaubern nutzt Alfa Tabellen aus dem klassischen Spiel, ebenfalls geschätzt.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "Im Fenster und hier. Wenn du nicht dabei bist, erscheint deine Zeile am Ende.",
	["En las dos armas"] = "Auf beiden Waffen",
	["En los mapas"] = "Auf den Karten",
	["En lugar de las del juego"] = "Statt der des Spiels",
	["En marcha"] = "Läuft",
	["En marcha hacia %s"] = "Unterwegs nach %s",
	["En mazmorra"] = "Im Dungeon",
	["En mazmorras y bandas"] = "In Dungeons und Schlachtzügen",
	["En mi zona"] = "In meinem Gebiet",
	["En otra zona: %s"] = "In einem anderen Gebiet: %s",
	["En pantalla"] = "Auf dem Bildschirm",
	["En pausa"] = "Pausiert",
	["En pausa dentro de la instancia"] = "Pausiert in der Instanz",
	["En pausa por ahora"] = "Vorerst pausiert",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "In Gasthäusern und Städten sammelst du Ruhebonus: Du bekommst doppelte EP pro Gegner, bis er aufgebraucht ist. Wenn du dich hier ausloggst, sammelt er sich auch.",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "In Gasthäusern und Städten sammelst du Ruhebonus: doppelte EP pro Gegner, bis er aufgebraucht ist.",
	["En qué orden aparecen."] = "In welcher Reihenfolge sie erscheinen.",
	["En solitario es lento: usa la varita para rematar."] = "Solo ist es langsam: Nutze deinen Zauberstab zum Erledigen.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "Solo: Setz Heilungen über Zeit und kämpf mit Zorn.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "Solo: Kämpf mit Schocks und heil dich zwischen den Monstern.",
	["En su ficha toca «Agregar a mi ruta»."] = "Klick in seinem Eintrag auf „Zu meiner Route hinzufügen“.",
	["En tu arma"] = "Auf deiner Waffe",
	["En tu marco"] = "Auf deinem Rahmen",
	["En tu plan"] = "In deinem Plan",
	["En tu registro"] = "In deinem Questlog",
	["En tus bolsas"] = "In deinen Taschen",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "In deinen Taschen, in der Beute, im Chat oder bei jedem Link: Alt+Klick öffnet den Guide, um es zu bekommen, oder, falls es keinen gibt, seinen Eintrag in der Enzyklopädie.",
	["En un aviso"] = "Als Hinweis",
	["En un aviso y en el chat"] = "Als Hinweis und im Chat",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "Bei einem Flug mit Zwischenstopps zeigt eine Zeile unter dem Timer, wo der nächste Halt ist und wie lange es noch dauert. Dafür muss der Flug-Timer an sein.",
	["En una instancia: la flecha vuelve al salir"] = "In einer Instanz: Der Pfeil kommt zurück, wenn du sie verlässt",
	["En una pestaña nueva"] = "In einem neuen Tab",
	["En unos segundos aparece tu build."] = "In ein paar Sekunden erscheint dein Build.",
	["En uso"] = "In Verwendung",
	["En uso, a tu gusto"] = "In Verwendung, nach deinem Geschmack",
	["En vivo"] = "Live",
	["En vivo si estás con un banquero; si no, la última foto."] = "Live, wenn du bei einem Bankier bist; sonst der letzte Stand.",
	["En vuelo: la flecha sigue al bajar"] = "Im Flug: Der Pfeil geht nach der Landung weiter",
	["En vuelo: la flecha sigue al bajar."] = "Im Flug: Der Pfeil macht nach der Landung weiter.",
	["Enanos"] = "Zwerge",
	["Encanta tu arma antes de pelear."] = "Verzaubere deine Waffe vor dem Kampf.",
	["Encantada"] = "Verzaubert",
	["Encantamiento"] = "Verzauberkunst",
	["Encender el registro"] = "Aufzeichnung einschalten",
	["Encender la pesca"] = "Angeln einschalten",
	["Encender las recomendadas"] = "Die empfohlenen einschalten",
	["Encenderla"] = "Einschalten",
	["Encenderlos"] = "Einschalten",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "An: Sie kommt in den Plan, auch wenn der Filter sie auslässt. Aus: Sie bleibt draußen.",
	["Encendido"] = "An",
	["Encendido y tecla"] = "Ein/Aus und Taste",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "An: Ein Doppelklick beim Angeln wirft erneut aus, mit Umschalt, Strg oder Alt holst du ein. Aus: umgekehrt.",
	["Enciclopedia"] = "Enzyklopädie",
	["Enciende las comodidades recomendadas"] = "Schalte die empfohlenen Komfortfunktionen ein",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "Schaltet die Änderungen unten für den Tooltip ein, der erscheint, wenn du mit der Maus über einen Charakter oder eine Kreatur fährst.",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "Schaltet die Änderungen unten für die Anprobe ein (Strg + Klick auf einen Gegenstand).",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "Schaltet die Änderungen unten ein; jede lässt sich einzeln ausschalten. Manche Addons passen ihre Knöpfe erst nach /reload an die eckige Form an.",
	["Enciende primero la guía en el minimapa."] = "Schalte zuerst den Guide auf der Minikarte ein.",
	["Enciende primero los servicios."] = "Schalte zuerst die Dienste ein.",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "Schalte sie ein, um im Kampf zu sehen, welche Fähigkeit jetzt am besten ist und welche folgen, in einem kleinen, verschiebbaren Symbol.",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "Schalte sie unten unter „Rahmen“ ein, um die Gesundheit deiner Gruppe zu sehen und mit einem Klick zu heilen.",
	["Enciéndelos en la página Curación."] = "Schalte sie auf der Seite Heilung ein.",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "Schalte sie ein, um die Gesundheit deiner Gruppe zu sehen und mit einem Klick zu heilen.",
	["Enemigo raro"] = "Seltener Gegner",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "Wurzle das Monster fest und geh auf Abstand, bevor du deine langen Zauber wirkst.",
	["Entendido"] = "Verstanden",
	["Entereza"] = "Seelenstärke",
	["Entra al juego con él una vez."] = "Logg dich einmal mit ihm ein.",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "Geh mit leerem Questlog rein: Gib ab, was du schon hast.",
	["Entrada"] = "Eingang",
	["Entrada enemiga"] = "Feindlicher Eingang",
	["Entradas de mazmorras"] = "Dungeon-Eingänge",
	["Entradas en el minimapa"] = "Eingänge auf der Minikarte",
	["Entraste a %s"] = "Du hast %s betreten",
	["Entraste a %s."] = "Du hast %s betreten.",
	["Entrega tus %d misiones listas"] = "Gib deine %d fertigen Quests ab",
	["Entregar"] = "Abgeben",
	["Entregar las completadas"] = "Abgeschlossene abgeben",
	["Entregar mis misiones"] = "Meine Quests abgeben",
	["Entregar misiones"] = "Quests abgeben",
	["Entregar solas las misiones de la guía"] = "Quests des Guides automatisch abgeben",
	["Entregarlas ahora"] = "Jetzt abgeben",
	["Entrenador"] = "Lehrer",
	["Entrenador al día"] = "Lehrer: alles gelernt",
	["Entrenador: %s, en %s."] = "Lehrer: %s, in %s.",
	["Entrenador: %s."] = "Lehrer: %s.",
	["Entrégala a %s."] = "Gib sie bei %s ab.",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "Er vergiftet und wirkt Blitze: Entferne das Gift, wenn du kannst.",
	["Equilibrada"] = "Ausgewogen",
	["Equilibrado"] = "Ausgewogen",
	["Equilibrio"] = "Gleichgewicht",
	["Equilibrio para subir"] = "Gleichgewicht zum Leveln",
	["Equipa tu caña de pescar"] = "Leg deine Angelrute an",
	["Equipo"] = "Ausrüstung",
	["Equipo %d %%"] = "Ausrüstung %d %%",
	["Equipo a punto de romperse."] = "Ausrüstung fast kaputt.",
	["Equipo y estadísticas"] = "Ausrüstung und Werte",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "Ausrüstung, Verbrauchsgüter, Questgegenstände, Materialien... unter einklappbaren Überschriften.",
	["Eres de la manada"] = "Du bist im Rudel",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "Du bist Stufe %d, empfohlen ist Stufe %d: Ab da sieht die Rechnung so aus.",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "Kurzer Dungeon mitten in Sturmwind. Die Gefangenen sitzen in Zellen an den Seiten: Geht langsam vor.",
	["Es de la otra facción"] = "Gehört zur anderen Fraktion",
	["Es de una misión."] = "Questgegenstand.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "Diesen Boss verlangt eine Quest der Allianz: Prüf deine Quests, bevor du reingehst.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "Der erste Boss und ein einfacher. Wenn er stirbt, öffnet der Gefangene deiner Fraktion die Tür zum Hof.",
	["Es el punto %d de %d de tu build."] = "Es ist Punkt %d von %d deines Builds.",
	["Es el que toca ahora."] = "Dieses ist jetzt dran.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "Der letzte Boss des Friedhofs. Er schleudert Flammen um sich: Wenn du auf Distanz kämpfst, bleib weg.",
	["Es el único lobo a la vista."] = "Das ist der einzige Wolf in Sicht.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "Groß, und man verirrt sich leicht: Folgt einer einzigen Person und lauft nicht allein los.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "Das ist Sneeds Maschine: Zerstört sie, dann kommt er zum Kämpfen heraus.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "Der erste Dungeon der Horde: kurz und gut, um Gruppenspiel zu lernen.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "Der erste große Dungeon der Allianz: Geht langsam vor und zieht eine Gruppe nach der anderen.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "Lang, mit zwei Eingängen. Viele Gegner sind aus Stein und schlagen hart zu.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "Lang, mit vielen Robotern: Manche legen Bomben oder lösen Alarme aus, die mehr Gegner herbeirufen.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Er ist langsam: Wenn du auf Distanz kämpfst, greif ihn an, während er näher kommt.",
	["Es muy veloz: frénalo si tu clase puede."] = "Er ist sehr schnell: Verlangsame ihn, wenn deine Klasse das kann.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "Er ist für Stufen %s, und du bist %d: Dir fehlen %d Stufen.",
	["Es para otra raza."] = "Sie ist für ein anderes Volk.",
	["Es raro del Cementerio y no siempre aparece."] = "Seltener Gegner auf dem Friedhof, nicht immer da.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "Seltener Gegner auf dem Friedhof, nicht immer da. Er vergiftet: Entferne das Gift.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "Seltener Gegner auf dem Friedhof, nicht immer da. Er kann Zauberwirker zum Schweigen bringen.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "Selten und nur ab und zu da. Er setzt Feuer um sich herum ein.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "Selten und in einer versteckten Höhle. Eine Fledermaus, die schnell zuschlägt.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "Selten und nicht immer da. Er schlägt für seine Stufe sehr hart zu: Zieht ihn vorsichtig.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "Selten und nicht immer da. Er trifft alle vor ihm hart.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "Selten. Er stellt ein Erdtotem auf: Zerstör es.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "Selten: nicht immer da. Er schläfert Spieler ein und explodiert mit Magie um sich herum.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "Ein einfacher: guter Moment, vor dem letzten Boss etwas zu trinken.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "Er ist ein Zauberwirker: Unterbrich ihn, wenn deine Klasse kann (Tritt, Schildhieb, Erdschock...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "Ein Schamane mit Totems: Zerstört die Totems, sie sind leicht zu töten.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "Ein Zwerg mit Schild: hält viel aus, hat aber keine Tricks.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "Ein starker Gegner in der Mine: Behandelt ihn wie einen kleinen Boss.",
	["Es un grupo: cada uno suelta su propio botín."] = "Es ist eine Gruppe: Jeder lässt seine eigene Beute fallen.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "Er ist ein Paladin und heilt sich mit Heiligem Licht. Unterbrich seine Heilung.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "Ein schneller Satyr, der vergiftet: Wenn deine Klasse Gifte entfernen kann, nutze es.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "Ein Trogg, der Blitze wirkt: Unterbrich ihn.",
	["Es una mejora para ti"] = "Das ist ein Upgrade für dich",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "Eine riesige Schildkröte mit viel Rüstung: schlägt langsam, aber hart zu.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "Eine sehr zähe Schildkröte, die aber nur zuschlägt: keine Tricks.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "Dieser Text enthält keinen Wert, den Alfa bewertet.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Diese Reihe ist noch nicht offen: Dir fehlen Punkte in diesem Zweig.",
	["Esa tecla ya tiene dueño"] = "Diese Taste ist schon belegt",
	["Escala de estadísticas"] = "Werteskala",
	["Escalas:"] = "Zwischenstopps:",
	["Escaneando..."] = "Scanne...",
	["Escanear ahora"] = "Jetzt scannen",
	["Escanear con Alfa"] = "Mit Alfa scannen",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "Vollständiger Scan: %s Gegenstände mit Preis (%s Auktionen).",
	["Escarcha"] = "Frost",
	["Escarcha para subir"] = "Frost zum Leveln",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "Blendet beim Angeln Namensplaketten und NPC-Namen aus (feindliche Gegner behalten ihren Namen), damit du den Schwimmer besser siehst und triffst.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "Blendet aus, was mehr Fertigkeit braucht, als du hast. Ohne diese Option erscheint es grau und blass.",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "Gib %s ein oder klick auf den Wolf an der Minikarte, um es zu öffnen. Es startet auf Heute, mit dem, was deine Klasse braucht; %s blendet das Guide-Fenster ein oder aus.",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "Gib %s ein und sag uns auf dem Discord von La Jauría Bescheid.",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "Gib oben den Namen eines Dungeons ein, um ihn zu suchen.",
	["Escribe el top %d en el chat de tu grupo o banda."] = "Schreibt das Top %d in den Chat deiner Gruppe oder deines Schlachtzugs.",
	["Escribe un nombre corto para reconocerla."] = "Gib einen kurzen Namen ein, an dem du sie erkennst.",
	["Escribir a %s"] = "An %s schreiben",
	["Escuchar"] = "Anhören",
	["Escuchar el aullido"] = "Heulen anhören",
	["Escudo"] = "Schild",
	["Escudo de relámpagos"] = "Blitzschlagschild",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Schild und Verteidigung: Du hältst alle Monster, damit deine Gruppe nicht leidet.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Schild und heiliges Licht: ein sehr zäher Tank, der sein eigenes Mana zurückholt.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "Schilde und vorbeugende Heilungen: Du hältst viel aus und unterstützt die Gruppe.",
	["Ese build es para otra clase."] = "Dieser Build ist für eine andere Klasse.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "Dieses Talent braucht zuerst ein anderes voll gelerntes Talent (der Pfeil im Baum).",
	["Ese texto es demasiado largo para un build."] = "Dieser Text ist zu lang für einen Build.",
	["Ese texto es demasiado largo para una cadena de escala."] = "Dieser Text ist zu lang für eine Werteskala.",
	["Ese texto no es una ruta de Alfa."] = "Dieser Text ist keine Alfa-Route.",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "Das ist kein Alfa-Build-Text. Er beginnt mit ALFA1;",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "Das ist kein Werteskala-Text. Er beginnt mit ( Pawn: v1: \"Name\": ...",
	["Espacio libre"] = "Freier Platz",
	["Espacio y dinero"] = "Platz und Geld",
	["Espada de dos manos"] = "Zweihandschwert",
	["Espada de una mano"] = "Einhandschwert",
	["Espalda"] = "Rücken",
	["Español, inglés y siete idiomas más, en toda la interfaz."] = "Spanisch, Englisch und sieben weitere Sprachen, im ganzen Interface.",
	["Espera %s"] = "Warte %s",
	["Espera a que el tanque tenga al enemigo bien agarrado antes de pegar fuerte."] = "Warte, bis der Tank den Gegner gut im Griff hat, bevor du hart zuschlägst.",
	["Espera a salir de combate para probarla."] = "Warte, bis du nicht mehr im Kampf bist, um es zu testen.",
	["Espera a salir de combate."] = "Warte, bis du nicht mehr im Kampf bist.",
	["Espera a terminar de entrar al juego."] = "Warte, bis du ganz eingeloggt bist.",
	["Espera · nivel %d"] = "Wartet · Stufe %d",
	["Espera: %s."] = "Wartet: %s.",
	["Esperan: %s."] = "Warten: %s.",
	["Espíritu"] = "Willenskraft",
	["Esquiva"] = "Ausweichen",
	["Esquivar"] = "Ausweichen",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "Diese Klasse hat in Alfa keine Werte-Gewichtung.",
	["Esta clase no tiene pesos de estadísticas."] = "Diese Klasse hat keine Werte-Gewichtung.",
	["Esta sesión"] = "Diese Sitzung",
	["Esta sesión, por recurso"] = "Diese Sitzung, nach Ressource",
	["Esta sesión: %s"] = "Diese Sitzung: %s",
	["Esta subasta no permite el escaneo completo."] = "Dieses Auktionshaus erlaubt keinen vollständigen Scan.",
	["Estadísticas"] = "Werte",
	["Este banco no vende más espacio."] = "Diese Bank verkauft keinen weiteren Platz.",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "Dieser Build schlägt enorm hart zu, hält aber wenig aus: Wähle gut, wann du reingehst.",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "Dieser Klick tut nichts. Wähle etwas dafür unter „Deine Maus“ auf der Seite Heilung.",
	["Este cliente no da el arte del mapa"] = "Dieser Client liefert keine Kartengrafik",
	["Este cliente no deja compartir"] = "Dieser Client erlaubt kein Teilen",
	["Este cliente no deja compartir marcadores."] = "Dieser Client erlaubt kein Teilen von Markierungen.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Dieser Client kann deine Belegung nicht selbst kopieren: Blizzards Klickzauber-Fenster wurde geöffnet, damit du sie dort einrichtest.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "Dieser Client hat keine Klickzauber von Blizzard. Deine Klicks funktionieren in Alfas Rahmen.",
	["Este paso no tiene punto en el mapa."] = "Dieser Schritt hat keinen Punkt auf der Karte.",
	["Este talento no está en tu build."] = "Dieses Talent ist nicht in deinem Build.",
	["Este tramo quedó vacío."] = "Diese Etappe ist leer geblieben.",
	["Estilo y sonido"] = "Stil und Klang",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Das lässt sich im Kampf nicht ändern. Versuch es nach dem Kampf.",
	["Esto no se puede vincular."] = "Das lässt sich nicht verlinken.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Er ist auf dem Friedhof. Er wirkt einen Schattenschmerz, der mit der Zeit Schaden macht.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Er ist im Wasser am Wasserfall: Lockt ihn an Land, bevor ihr kämpft.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "In der Waffenkammer. Wenn er schreit, wirbelt er mit seiner Axt und trifft alle in der Nähe: Geh weg.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "In der Bibliothek, mit seinen Hunden: Tötet sie zuerst oder nutzt Flächenangriffe.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Versteckt in der Kathedrale. Er verflucht und heilt sich: Unterbrich ihn.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Voller Stacheleber in Dornentunneln: Zieht nur wenige auf einmal.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Um ihn herum arbeiten Goblins: Zieht zuerst die Goblins, einen nach dem anderen.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Murlocs umgeben ihn: Zieht seine Freunde vor ihm.",
	["Estás aquí"] = "Du bist hier",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Du bist bei einem Bankier: In seinem Fenster lagerst du mit einem Klick ein, was du willst.",
	["Estás dentro"] = "Du bist drinnen",
	["Estás descansando"] = "Du erholst dich",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Du bist im Kampf. Talente lassen sich nur außerhalb des Kampfes ändern: Beende den Kampf und versuch es erneut.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Du bist im Kampf: Such die Ausrüstung, wenn der Kampf vorbei ist.",
	["Estás en combate: lo que cambies se aplica al salir."] = "Du bist im Kampf: Änderungen gelten, sobald du ihn verlässt.",
	["Estás en una instancia: la flecha vuelve al salir."] = "Du bist in einer Instanz: Der Pfeil kommt zurück, wenn du sie verlässt.",
	["Estás mirando otro paso"] = "Du siehst dir einen anderen Schritt an",
	["Evento"] = "Ereignis",
	["Evita golpes críticos y aplastantes: lo más importante para un tanque."] = "Verhindert kritische und schmetternde Schläge: der wichtigste Wert für einen Tank.",
	["Evitar misiones de grupo"] = "Gruppenquests meiden",
	["Experiencia"] = "Erfahrung",
	["Explicar por qué"] = "Erklären, warum",
	["Fallas menos golpes, sobre todo contra monstruos de nivel más alto que el tuyo."] = "Du verfehlst seltener, vor allem gegen Monster über deiner Stufe.",
	["Fallas menos golpes."] = "Du verfehlst seltener.",
	["Fallas menos: con dos armas fallas mucho sin esto."] = "Du verfehlst seltener: Mit zwei Waffen verfehlst du ohne das oft.",
	["Fallida"] = "Fehlgeschlagen",
	["Falta el final del texto: cópialo completo."] = "Das Ende des Textes fehlt: Kopiere ihn vollständig.",
	["Falta el paquete de datos de Alfa (Alfa_Codex): vuelve a instalar Alfa completo."] = "Alfas Datenpaket (Alfa_Codex) fehlt: Installiere Alfa komplett neu.",
	["Falta en un arma"] = "Fehlt auf einer Waffe",
	["Falta la carpeta Alfa_Codex: reinstala Alfa."] = "Der Ordner Alfa_Codex fehlt: Installiere Alfa neu.",
	["Falta la función del juego para enviar mensajes de addon. Tu grupo sí se ve."] = "Die Spielfunktion zum Senden von Addon-Nachrichten fehlt. Deine Gruppe siehst du trotzdem.",
	["Faltan las texturas de detalle en la carpeta Media de Alfa_Mundo: el mapa se dibuja solo con el arte del juego."] = "Die Detailtexturen fehlen im Media-Ordner von Alfa_Mundo: Die Karte wird nur mit der Grafik des Spiels gezeichnet.",
	["Faltan los datos de las mazmorras"] = "Die Dungeon-Daten fehlen",
	["Faltan precios"] = "Preise fehlen",
	["Faltan precios de algunos materiales."] = "Für einige Materialien fehlen Preise.",
	["Faltan precios de sus materiales: escanea la subasta."] = "Für die Materialien fehlen Preise: Scanne das Auktionshaus.",
	["Fantasma"] = "Geist",
	["Feliz"] = "Glücklich",
	["Fija"] = "Fixiert",
	["Fijar"] = "Fixieren",
	["Fijar marcos"] = "Rahmen fixieren",
	["Filones y depósitos de mineral."] = "Erzadern und Erzvorkommen.",
	["Fin de tu ruta: arma la siguiente en la página Ruta de Alfa."] = "Ende deiner Route: Erstelle die nächste auf Alfas Seite Route.",
	["Fin del camino"] = "Ende des Pfades",
	["Final de %s"] = "Ende von %s",
	["Flecha de mejora"] = "Upgrade-Pfeil",
	["Flecha puesta"] = "Pfeil gesetzt",
	["Flechas"] = "Pfeile",
	["Fondos transparentes para ver el mundo detrás y el color de acento que elijas."] = "Durchsichtige Hintergründe, die die Welt dahinter zeigen, in der Akzentfarbe deiner Wahl.",
	["Forma"] = "Gestalt",
	["Forma felina para matar rápido y forma de oso para las peleas difíciles; casi nunca necesitas beber."] = "Katzengestalt, um schnell zu töten, und Bärengestalt für schwere Kämpfe; du musst fast nie trinken.",
	["Forma normal"] = "Normale Gestalt",
	["Foto: %s"] = "Stand: %s",
	["Fragmentos de alma"] = "Seelensplitter",
	["Frena a los que huyen y te deja escapar de una mala pelea."] = "Bremst Fliehende und lässt dich aus einem schlechten Kampf entkommen.",
	["Frena a los que huyen y te salva de malas peleas."] = "Bremst Fliehende und rettet dich aus schlechten Kämpfen.",
	["Frena a todos los rivales cercanos."] = "Verlangsamt alle Gegner in der Nähe.",
	["Fuego"] = "Feuer",
	["Fuego interno"] = "Inneres Feuer",
	["Fuego para subir"] = "Feuer zum Leveln",
	["Fuera de combate es el mejor momento"] = "Außerhalb des Kampfes ist der beste Moment",
	["Fuera de este plan: %s (%s)."] = "Nicht in diesem Plan: %s (%s).",
	["Fuera de tu plan de misiones"] = "Nicht in deinem Questplan",
	["Fuera del plan"] = "Außerhalb des Plans",
	["Fuerza"] = "Stärke",
	["Furia"] = "Furor",
	["Furia con dos armas"] = "Furor mit zwei Waffen",
	["Furia con todo el daño posible: más precisión, Ejecutar mejorado y críticos enormes. Muy rápido matando, pero frágil."] = "Furor mit allem Schaden, der geht: mehr Trefferchance, Verbessertes Hinrichten und riesige Krits. Tötet sehr schnell, ist aber zerbrechlich.",
	["Furia contra jugadores"] = "Furor für PvP",
	["Furia desatada"] = "Entfesselter Furor",
	["Furia para grupo"] = "Furor für Gruppen",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "Furor für den Kampf gegen Spieler: enorm viel Schaden, Verbesserte Berserkerwut gegen Furcht und öfter Abfangen, damit du den Gegner nicht loslässt.",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "Blutrausch gibt dir mehr Wut, um schwere Kämpfe zu beginnen.",
	["Gana un poco de XP y Alfa calcula cuánto te falta."] = "Sammle ein paar EP, dann berechnet Alfa, wie lange es noch dauert.",
	["Gana un poco de XP y Alfa lo calcula"] = "Sammle etwas EP und Alfa rechnet es aus",
	["Ganado"] = "Erhalten",
	["Ganado %s"] = "Verdient: %s",
	["Ganado: %s. Gastado: %s. Suma tus sesiones de hoy con este personaje."] = "Verdient: %s. Ausgegeben: %s. Zählt die heutigen Sitzungen dieses Charakters zusammen.",
	["Ganas de más"] = "Mehrgewinn",
	["Garra: suma puntos de combo."] = "Klaue: baut Combopunkte auf.",
	["Gasta la ira sobrante en Golpe heroico; si llegas a 100 de ira, la estás desperdiciando."] = "Steck übrige Wut in Heldenhafter Stoß; wenn du 100 Wut erreichst, verschwendest du sie.",
	["Gastado"] = "Ausgegeben",
	["General, por categorías o por bolsa, y depósito rápido al banco."] = "Übersicht, nach Kategorie oder nach Tasche, und schnelles Einlagern in die Bank.",
	["Gnomos"] = "Gnome",
	["Golpe"] = "Treffer",
	["Golpe con hechizos"] = "Zaubertreffer",
	["Golpe crítico"] = "Kritischer Treffer",
	["Golpe fuerte que además reduce las curas del rival."] = "Ein starker Schlag, der außerdem die Heilung des Gegners senkt.",
	["Golpe heroico cuesta menos ira: lo usarás en cada pelea."] = "Heldenhafter Stoß kostet weniger Wut: Du nutzt ihn in jedem Kampf.",
	["Golpe heroico más barato."] = "Günstigerer Heldenhafter Stoß.",
	["Golpe heroico más barato: amenaza extra con la ira que sobra."] = "Günstigerer Heldenhafter Stoß: zusätzliche Bedrohung mit übriger Wut.",
	["Golpe heroico más barato: la ira sobrante se vuelve amenaza."] = "Günstigerer Heldenhafter Stoß: Übrige Wut wird zu Bedrohung.",
	["Golpe heroico: tu golpe más fuerte mientras subes."] = "Heldenhafter Stoß: dein stärkster Schlag beim Leveln.",
	["Golpe mental: mucho daño, cada vez que esté listo."] = "Gedankenschlag: viel Schaden, jedes Mal, wenn er bereit ist.",
	["Golpe mortal: tu golpe más fuerte, cada vez que esté listo."] = "Tödlicher Stoß: dein stärkster Schlag, jedes Mal, wenn er bereit ist.",
	["Golpe siniestro: suma puntos de combo."] = "Finsterer Stoß: baut Combopunkte auf.",
	["Golpea a los que tiene alrededor: gíralo lejos del grupo."] = "Er trifft alle um sich herum: Dreh ihn von der Gruppe weg.",
	["Golpea a todos los que están cerca y los avienta: si peleas cuerpo a cuerpo, cuida tu vida."] = "Er trifft alle in der Nähe und schleudert sie weg: Wenn du im Nahkampf kämpfst, achte auf deine Gesundheit.",
	["Golpea a todos los que tiene enfrente: ataca desde su espalda si peleas cuerpo a cuerpo."] = "Er trifft alle vor ihm: Greif von hinten an, wenn du im Nahkampf kämpfst.",
	["Golpea a todos los que tiene enfrente: si peleas cuerpo a cuerpo, ataca por detrás."] = "Er trifft alle vor ihm: Im Nahkampf greifst du von hinten an.",
	["Golpea a varios enemigos a tu alrededor."] = "Trifft mehrere Gegner um dich herum.",
	["Golpea fuerte con su cuchilla y hace sangrar: vigila la vida del tanque."] = "Er schlägt hart mit seinem Hackbeil zu und verursacht Blutungen: Achte auf die Gesundheit des Tanks.",
	["Golpea y avienta al tanque: regresa a tu lugar rápido."] = "Er schlägt den Tank weg: Kehr schnell an deinen Platz zurück.",
	["Golpea y frena a todos los enemigos que tienes cerca."] = "Trifft und verlangsamt alle Gegner in deiner Nähe.",
	["Golpeas a dos a la vez: puedes juntar monstruos de dos en dos."] = "Du triffst zwei gleichzeitig: Du kannst Monster zu zweit ziehen.",
	["Grafito"] = "Graphit",
	["Grafito con esquinas cortadas y el verde de La Jauría. El de siempre."] = "Graphit mit abgeschrägten Ecken und dem Grün von La Jauría. Der Bewährte.",
	["Gran aumento de daño para los jefes."] = "Großer Schadensschub gegen Bosse.",
	["Gran aumento de daño y te libra del miedo."] = "Großer Schadensschub, und er befreit dich von Furcht.",
	["Gran aumento de daño."] = "Großer Schadensschub.",
	["Gran golpe de escudo con mucha amenaza."] = "Ein großer Schildschlag mit viel Bedrohung.",
	["Gratis"] = "Kostenlos",
	["Gratis tras vencer a un enemigo, y te cura."] = "Kostenlos nach einem besiegten Gegner, und er heilt dich.",
	["Grito de batalla"] = "Schlachtruf",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "Schlachtruf für Krieger; Arkane Intelligenz und eine Rüstung für Magier; Seelenstärke und Inneres Feuer für Priester; und das Passende für jede Klasse.",
	["Grupo"] = "Gruppe",
	["Grupo de %d"] = "Gruppe mit %d",
	["Grupo de 5"] = "Gruppe mit 5",
	["Guarda %d misiones: las entregas en una guía que sigue."] = "Behalte %d Quests: Du gibst sie in einem späteren Guide ab.",
	["Guarda Grito intimidador para cuando estés en peligro."] = "Heb dir Drohruf für Gefahrenmomente auf.",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "Heb dir Schildwall für die schlimmsten Momente des Bosses auf.",
	["Guardar"] = "Behalten",
	["Guardar %d"] = "%d behalten",
	["Guardar como marcador"] = "Als Markierung speichern",
	["Guardar y seguir"] = "Speichern und folgen",
	["Guardas ira al cambiar de actitud."] = "Du behältst Wut beim Haltungswechsel.",
	["Guardas tu ira al cambiar de actitud; así Cargar, Abrumar y Revancha salen casi gratis."] = "Du behältst deine Wut beim Haltungswechsel; so sind Sturmangriff, Überwältigen und Rache fast gratis.",
	["Guardaste %d objeto en el banco."] = "Du hast %d Gegenstand in der Bank eingelagert.",
	["Guardaste %d objetos en el banco."] = "Du hast %d Gegenstände in der Bank eingelagert.",
	["Guerrero"] = "Krieger",
	["Guiarme"] = "Hinführen",
	["Guía"] = "Guide",
	["Guía abierta en una pestaña nueva: sigue la flecha."] = "Guide in einem neuen Tab geöffnet: Folge dem Pfeil.",
	["Guía actual"] = "Aktueller Guide",
	["Guía para desbloquearla en marcha"] = "Guide zum Freischalten läuft",
	["Guía: %s"] = "Guide: %s",
	["Guíame"] = "Führ mich",
	["Guíame aquí"] = "Führ mich hierher",
	["Guíame te lleva paso a paso."] = "„Führ mich“ führt dich Schritt für Schritt.",
	["Guías"] = "Guides",
	["Guías con %s"] = "Guides mit %s",
	["Guías de la comunidad"] = "Community-Guides",
	["Guías y planes"] = "Guides und Pläne",
	["Habilidad en esta sesión"] = "Fertigkeit in dieser Sitzung",
	["Habilidades más baratas."] = "Günstigere Fähigkeiten.",
	["Habilidades más baratas: más golpes de amenaza."] = "Günstigere Fähigkeiten: mehr Bedrohungsschläge.",
	["Habilidades por entrenar"] = "Fähigkeiten zum Trainieren",
	["Habilidades que vigila la ayuda de Blizzard"] = "Fähigkeiten, die Blizzards Kampfassistent beobachtet",
	["Habla con %s"] = "Sprich mit %s",
	["Habla con un banquero para comprarla."] = "Sprich mit einem Bankier, um ihn zu kaufen.",
	["Hablar"] = "Reden",
	["Hace heridas que sangran: vigila la vida del tanque."] = "Er verursacht blutende Wunden: Achte auf die Gesundheit des Tanks.",
	["Hace sangrar al enemigo: ponlo al empezar la pelea."] = "Lässt den Gegner bluten: Setz es zu Kampfbeginn ein.",
	["Hacen falta al menos 3 lugares distintos de ese recurso en la zona."] = "Eine Route braucht mindestens 3 verschiedene Fundorte dieser Ressource im Gebiet.",
	["Hacer oro"] = "Gold machen",
	["Hacha de dos manos"] = "Zweihandaxt",
	["Hacha de una mano"] = "Einhandaxt",
	["Hacia dónde se acomodan tus compañeros."] = "In welche Richtung deine Gruppenmitglieder angeordnet werden.",
	["Hacia:"] = "Ziel:",
	["Hacia: %s"] = "Ziel: %s",
	["Hasta el nivel 20 usa un arma de dos manos; luego cambia a dos armas de una mano."] = "Nutze bis Stufe 20 eine Zweihandwaffe; wechsle danach auf zwei Einhandwaffen.",
	["Hasta mi nivel"] = "Bis zu meiner Stufe",
	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "Manche Gegner verwandeln sich in Wölfe, andere versetzen in Furcht: Lauft nicht in Panik los, wartet es ab.",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "Hier gibt es viel Wasser: Wenn du tauchst, achte auf deine Atemleiste und tauch zum Luftholen auf.",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "Viele Untote und Stacheleber: Bringt etwas gegen Krankheiten mit, wenn eure Gruppe das kann.",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "Viele Troggs und Feuerelementare stehen dicht beieinander: Zieht ein oder zwei Gruppen auf einmal, nicht mehr.",
	["Hay una guía de Alfa"] = "Es gibt einen Alfa-Guide",
	["Haz clic derecho (o Mayús+clic) en el mapa donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras."] = "Mach einen Rechtsklick (oder Umschalt+Klick) auf die Karte, wo du eine willst: Gib ihr Namen, Symbol und Farbe, und der Pfeil führt dich hin, wann du willst.",
	["Haz clic en un marco de ejemplo"] = "Klick auf einen Beispielrahmen",
	["Haz clic y pulsa la tecla que quieras (Esc cancela). Clic derecho la quita."] = "Klick und drück die gewünschte Taste (Esc bricht ab). Rechtsklick entfernt sie.",
	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "Doppel-Rechtsklick in die Welt wirft die Angel aus, ganz ohne Taste. Nie im Kampf oder im Flug.",
	["Haz doble clic derecho en el mundo para lanzar. Cuando pique, haz clic derecho sobre el corcho para recoger."] = "Doppel-Rechtsklick in die Welt wirft aus. Wenn etwas anbeißt, klick mit rechts auf den Schwimmer, um einzuholen.",
	["Hecha"] = "Erledigt",
	["Hecha %d veces"] = "%d-mal erledigt",
	["Hechas"] = "Erledigt",
	["Hechizo del preajuste"] = "Zauber aus der Voreinstellung",
	["Hechizo desconocido"] = "Unbekannter Zauber",
	["Hechizo elegido por ti"] = "Von dir gewählter Zauber",
	["Hechizo nuevo para tus clics de Curación. Ábrelo en /alfa curacion."] = "Neuer Zauber für deine Heilungsklicks. Öffne /alfa curacion.",
	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "Schattenzauber mit Schaden über Zeit: der Priester, der solo am besten levelt, fast ohne Rast.",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "Zauber aus der Ferne und Wurzeln, damit dich das Monster nicht erreicht. Am Ende kommt die Mondkingestalt.",
	["Hecho"] = "Fertig",
	["Hender armadura más barato."] = "Günstigeres Rüstung zerreißen.",
	["Hender armadura más barato: amenaza constante."] = "Günstigeres Rüstung zerreißen: stetige Bedrohung.",
	["Hender armadura más barato: más amenaza a varios enemigos."] = "Günstigeres Rüstung zerreißen: mehr Bedrohung auf mehrere Gegner.",
	["Hender armadura: amenaza constante y el enemigo recibe más daño."] = "Rüstung zerreißen: stetige Bedrohung, und der Gegner erleidet mehr Schaden.",
	["Herboristería"] = "Kräuterkunde",
	["Herramienta"] = "Werkzeug",
	["Herrería"] = "Schmiedekunst",
	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "Schmiedekunst stellt für deine Stufe sehr gute Waffen und Plattenrüstung her, und Bergbau liefert dir das Material gratis.",
	["Herrería fabrica escudos y piezas resistentes."] = "Schmiedekunst stellt Schilde und robuste Teile her.",
	["Herrería fabrica escudos y placas con defensa y aguante, justo lo que un tanque necesita."] = "Schmiedekunst stellt Schilde und Platte mit Verteidigung und Ausdauer her, genau das, was ein Tank braucht.",
	["Hielo"] = "Eis",
	["Hierbas"] = "Kräuter",
	["Hombros"] = "Schultern",
	["Honor"] = "Ehre",
	["Horda"] = "Horde",
	["Hoy"] = "Heute",
	["Hoy en números"] = "Heute in Zahlen",
	["Hoy te guía"] = "„Heute“ führt dich",
	["Hoy, Aventura, Personaje, Mundo, Oficios y Manada en una sola ventana: %s o el lobo del minimapa."] = "Heute, Abenteuer, Charakter, Welt, Berufe und Rudel in einem einzigen Fenster: %s oder der Wolf an der Minikarte.",
	["Hoy, a tu clase"] = "Heute, für deine Klasse",
	["Huella"] = "Pfotenabdruck",
	["Humanos"] = "Menschen",
	["Huracán: golpea a todos a tu alrededor."] = "Wirbelwind: trifft alle um dich herum.",
	["Iconos de viaje en el minimapa"] = "Reisesymbole auf der Minikarte",
	["Igual que lo tuyo"] = "Gleich wie deins",
	["Igual que los otros señores: lanza rayos y se cura. Interrumpe su curación."] = "Wie die anderen Fürsten: Er wirkt Blitze und heilt sich. Unterbrich seine Heilung.",
	["Importa una cadena de escala de estadísticas y usa, renombra, exporta o borra las escalas que tienes."] = "Importiere einen Werteskala-Text und benutze, benenne um, exportiere oder lösche die Skalen, die du hast.",
	["Importado"] = "Importiert",
	["Importado: %s. Ya puedes seguirlo."] = "Importiert: %s. Du kannst ihm jetzt folgen.",
	["Importar"] = "Importieren",
	["Importar un build"] = "Einen Build importieren",
	["Importar una ruta"] = "Route importieren",
	["Importar..."] = "Importieren...",
	["Ingeniería"] = "Ingenieurskunst",
	["Ingeniería da aturdimientos y trucos que ganan duelos; Minería da el material."] = "Ingenieurskunst bringt Betäubungen und Tricks, die Duelle gewinnen; Bergbau liefert das Material.",
	["Ingeniería da granadas y redes para controlar al rival; Minería da el material."] = "Ingenieurskunst bringt Granaten und Netze, um den Gegner zu kontrollieren; Bergbau liefert das Material.",
	["Ingeniería da granadas, redes y bombas que deciden peleas contra jugadores; Minería da el material."] = "Ingenieurskunst bringt Granaten, Netze und Bomben, die Kämpfe gegen Spieler entscheiden; Bergbau liefert das Material.",
	["Ingeniería te salva con trucos de escape; Sastrería hace tu ropa."] = "Ingenieurskunst rettet dich mit Fluchttricks; Schneiderei macht deine Kleidung.",
	["Inicio"] = "Start",
	["Inicio de Alfa"] = "Alfa-Start",
	["Instantánea: úsala cada vez que esté lista."] = "Spontan: Nutze sie jedes Mal, wenn sie bereit ist.",
	["Instructor"] = "Lehrer",
	["Instructor de %s"] = "Lehrer für %s",
	["Instructores"] = "Lehrer",
	["Instructores de %s"] = "Lehrer für %s",
	["Intelecto"] = "Intelligenz",
	["Intelecto Arcano"] = "Arkane Intelligenz",
	["Intentar ahora"] = "Jetzt versuchen",
	["Intentar otra vez"] = "Erneut versuchen",
	["Interceptar más seguido: el rival no se escapa."] = "Öfter Abfangen: Der Gegner entkommt dir nicht.",
	["Interrumpes hechizos y los silencias."] = "Du unterbrichst Zauber und bringst den Zaubernden zum Schweigen.",
	["Interrumpes y silencias hechizos."] = "Du unterbrichst Zauber und bringst Zaubernde zum Schweigen.",
	["Invitar"] = "Einladen",
	["Invitar al grupo"] = "In Gruppe einladen",
	["Invitar, comerciar, susurrar…"] = "Einladen, handeln, flüstern…",
	["Invitaste a %s a tu grupo."] = "Du hast %s in deine Gruppe eingeladen.",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "Er beschwört einen Ebergeist: Tötet ihn oder lasst ihn von jemandem tanken.",
	["Invócalo antes de pelear."] = "Beschwöre ihn vor dem Kampf.",
	["Ir"] = "Los",
	["Ir al mapa del juego"] = "Zur Spielkarte",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "Wut beim Brechen einer Furcht: Gegner setzen oft Furcht gegen dich ein.",
	["Ira aunque el rival huya o te frene."] = "Wut, auch wenn der Gegner flieht oder dich verlangsamt.",
	["Ira constante en peleas largas contra jefes."] = "Stetige Wut in langen Bosskämpfen.",
	["Ira constante."] = "Stetige Wut.",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "Stetige Wut: Dir gehen nie die Fähigkeiten aus.",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "Gratis-Wut alle paar Sekunden, auch wenn dich niemand trifft.",
	["Izquierdo"] = "Links",
	["JcJ"] = "PvP",
	["Jefe"] = "Boss",
	["Jefe %d por descubrir"] = "Boss %d, noch zu entdecken",
	["Jefe final"] = "Endboss",
	["Jefes"] = "Bosse",
	["Jefes vencidos"] = "Besiegte Bosse",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "Besiegte Bosse, abgeschlossene Dungeons und notierte Beute dieses Charakters. Deine Einstellungen bleiben.",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "Bosse, Beute und der Eingang jedes Dungeons und Schlachtzugs.",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "Spiel jeden Charakter einmal, und Alfa merkt sich seine Taschen und seine Bank.",
	["Juega siempre en actitud defensiva con escudo."] = "Spiel immer in Verteidigungshaltung mit Schild.",
	["Junta %d de %s"] = "Sammle %d %s",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "Zieh zwei Monster und nutze Weitreichende Stöße: So levelst du schneller.",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "Zieh zwei oder drei Monster, nutze Donnerknall und Rache: Du levelst sicher und ohne Rast.",
	["Junta los montones y acomoda tus objetos con un clic."] = "Stapelt und ordnet deine Gegenstände mit einem Klick.",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "Stapelt und ordnet deine Gegenstände. Nicht im Kampf.",
	["Junta materiales de tu profesión donde más hay."] = "Sammle Materialien deines Berufs dort, wo es am meisten gibt.",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "Sammle Materialien deines Berufs, mit ein paar EP-Quests dazwischen.",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "Zieh mehrere Monster: Deine heiligen Schläge treffen alle.",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "Alles aus dem Spiel wird gesammelt. Das passiert nur beim ersten Öffnen.",
	["Juntar los materiales de mi profesión"] = "Materialien meines Berufs sammeln",
	["Juntar materiales para vender"] = "Materialien zum Verkaufen sammeln",
	["Juntar nodos cercanos al alejar"] = "Nahe Vorkommen beim Herauszoomen bündeln",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "Neben der Lupe der Spielkarte: die Ebenen, der Fokusmodus und „Alfas Karte“, um zu Alfas Karte zu wechseln.",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "B, Umschalt+B, die Taste jeder Tasche und Händler öffnen Alfas Fenster. Schalte es aus, um zu denen des Spiels zurückzukehren.",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "La Jauría auf der Karte",
	["La Jauría son todos los que usan Alfa. Si aceptas, quienes también comparten te ven en su mapa y te pueden seguir con la flecha, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase, nunca dentro de mazmorras. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "La Jauría sind alle, die Alfa nutzen. Wenn du zustimmst, sehen dich alle, die auch teilen, auf ihrer Karte und können dir mit dem Pfeil folgen, und du ihnen. Gesendet werden dein Gebiet, deine Position, deine Stufe und deine Klasse, nie in Dungeons. Deine Gruppe siehst du immer. Ändere es jederzeit in La Jauría.",
	["La Jauría son todos los que usan Alfa. Si compartes tu ubicación, te ven en su mapa y tú a ellos: quién anda cerca, dónde y, con un clic, la flecha te lleva. Tu grupo se ve siempre, compartas o no."] = "La Jauría sind alle, die Alfa nutzen. Wenn du deinen Standort teilst, sehen sie dich auf ihrer Karte und du sie: wer in der Nähe ist, wo, und mit einem Klick führt dich der Pfeil hin. Deine Gruppe siehst du immer, ob du teilst oder nicht.",
	["La Jauría te ve"] = "La Jauría sieht dich",
	["La Jauría: estado"] = "La Jauría: Status",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría: dein Rudel auf der Karte, Folgen und der Clan (/alfa manada ayuda)",
	["La Jauría: tus comandos"] = "La Jauría: deine Befehle",
	["La ayuda de rotación está apagada"] = "Die Rotationshilfe ist aus",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "Die Gesundheitsleiste in der Klassenfarbe jedes Mitglieds. Aus: grüne Leiste und der Name in seiner Farbe.",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "Die mitgelieferte Datenbank enthält %s Fundorte in %d Gebieten. Du hast %s entdeckt.",
	["La bienvenida con las novedades de esta versión."] = "Die Begrüßung mit den Neuerungen dieser Version.",
	["La búsqueda de lugares cercanos no está disponible."] = "Die Suche nach Orten in der Nähe ist nicht verfügbar.",
	["La cadena no trae talentos válidos."] = "Der Text enthält keine gültigen Talente.",
	["La cura de ese clic pasa al botón central."] = "Die Heilung dieses Klicks wandert auf die mittlere Maustaste.",
	["La derecha"] = "Rechts",
	["La empieza un objeto"] = "Startet durch einen Gegenstand",
	["La enciclopedia de La Jauría"] = "Die Enzyklopädie von La Jauría",
	["La enciclopedia no puede abrir todavía"] = "Die Enzyklopädie kann sich noch nicht öffnen",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "Der Eingang jedes Dungeons auf der Minikarte, in Grün die, die du schon gemacht hast. Die Weltkarte markiert sie bereits mit „Dungeon-Eingänge“.",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "Der Pfeil bewegt sich mit der Spur und hält an, wenn du ankommst.",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "Der Pfeil folgt Wegen am Boden um Klippen, Wasser und Mauern herum, auf Alfas Wegekarten. Aus: Er zeigt direkt auf jede Station.",
	["La flecha sigue en el paso de ahora."] = "Der Pfeil bleibt beim aktuellen Schritt.",
	["La flecha te lleva a %s."] = "Der Pfeil führt dich zu %s.",
	["La flecha te lleva aquí."] = "Der Pfeil führt dich hierher.",
	["La flecha te lleva de un lugar al siguiente."] = "Der Pfeil führt dich von einem Ort zum nächsten.",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "Der Pfeil hat ein anderes Ziel: Du folgst %s nicht mehr.",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "Der Pfeil nutzt Flüge und deinen Ruhestein, wenn es sich lohnt.",
	["La flecha ya no sigue tu ruta de farmeo."] = "Der Pfeil folgt deiner Farmroute nicht mehr.",
	["La guía en el minimapa"] = "Der Guide auf der Minikarte",
	["La guía que mejor te queda por tu nivel y donde estás."] = "Der Guide, der für deine Stufe und deinen Ort am besten passt.",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "Der Guide, dem du folgst, dein aktueller Schritt und alles rund um Guides mit einem Klick.",
	["La guía te lleva a entrenar en %d pasos."] = "Der Guide führt dich in %d Schritten zum Training.",
	["La guía te lleva a quien recibe cada una."] = "Der Guide führt dich zu dem, der jede annimmt.",
	["La haces de paso: abre %s."] = "Du machst sie nebenbei: Sie öffnet %s.",
	["La haré"] = "Mach ich",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "Die Schrift des Designs (Inter bei Alfas eigenem, Fira Sans bei Halo, die des Spiels bei den anderen) oder eine deiner Wahl.",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "Die Liste ist aus: Schalte „Deine Soundliste“ unter Komfort ein (/alfa comodidades).",
	["La lista por nivel y tu progreso."] = "Die Liste nach Stufe und dein Fortschritt.",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "Blizzards Zeitleiste sagt, welcher Angriff wann kommt, und die großen Meldungen zeigen, was gefährlich ist. Alfa erfindet keine Hinweise: Du schaltest sie in den Einstellungen ein und passt sie an.",
	["La línea del camino también en el minimapa."] = "Die Routenlinie auch auf der Minikarte.",
	["La manada a la vista"] = "Das Rudel in Sicht",
	["La manada aúlla contigo."] = "Das Rudel heult mit dir.",
	["La manada te saluda al abrir Alfa por primera vez en la sesión."] = "Das Rudel begrüßt dich, wenn du Alfa zum ersten Mal in einer Sitzung öffnest.",
	["La mazmorra para mi nivel"] = "Der Dungeon für meine Stufe",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "Der Dungeon für deine Stufe, seine Bosse, Beute, Quests und Tipps.",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "Der Dungeon für deine Stufe, seine Quests und wie du hinkommst.",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "Der Dungeon für deine Stufe; mit einem Namen dieser Dungeon (auch: progreso, ajustes)",
	["La pesca de Alfa está apagada"] = "Alfas Angeln ist aus",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "Trefferchance ist der wichtigste Wert: Mit zwei Waffen verfehlst du ohne sie oft.",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "Die Seite Taschen; „open“ öffnet deine Taschen und „bank“ deine Bank",
	["La que te toca, con sus misiones y su botín."] = "Der passende für dich, mit seinen Quests und seiner Beute.",
	["La recoges ahora"] = "Du nimmst sie jetzt an",
	["La recomendada para ti y todas las demás"] = "Der für dich empfohlene und alle anderen",
	["La recomendada para ti y todas las demás."] = "Der für dich empfohlene und alle anderen.",
	["La ruta más rápida desde tu nivel, misión por misión."] = "Die schnellste Route ab deiner Stufe, Quest für Quest.",
	["La ruta no trae tramos."] = "Die Route enthält keine Etappen.",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "Die Route führt dich zu %s. Der Pfeil ist aus: Schalte ihn unter Einstellungen > Guide ein, um ihn zu sehen.",
	["La sacas de tu plan."] = "Du nimmst sie aus deinem Plan.",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "Der nächste Platz kostet %s, und das reicht noch nicht.",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "Das Auktionshaus erlaubt alle 15 Minuten einen vollständigen Scan. Noch %s.",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "Das Auktionshaus hat den Scan nicht angenommen. Versuch es später erneut.",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "Das Auktionshaus hat keine Auktionen geschickt. Versuch es später erneut.",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "Das Auktionshaus hat nicht geantwortet. Vielleicht läuft die Wartezeit noch: Versuch es in ein paar Minuten.",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "Die Summe dessen, was Alfa von jedem Charakter gespeichert hat (deiner ist aktuell).",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "Die Taste des Knopfes in deiner Leiste mit dieser Fähigkeit, auf dem Symbol.",
	["La tecla del mapa abre este mapa"] = "Die Kartentaste öffnet diese Karte",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "Die Taste, die die Spielkarte öffnet (M), öffnet Alfas Karte; darin bringt dich ein Knopf zur Spielkarte. Schalte es aus, und die Taste öffnet wieder die Spielkarte. Du kannst ihr auch eine eigene Taste geben unter Optionen > Tastaturbelegung > Alfa.",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "Die Taste, die du in deinem anderen Angel-Addon benutzt hast (%s), angelt jetzt mit Alfa.",
	["La tomo otra vez"] = "Ich nehme sie noch mal an",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "Der Schredder schleudert Leute herum: Zieh seine Aufmerksamkeit schnell zurück.",
	["La tuya tiene %d semanas: salen seguido."] = "Deine ist %d Wochen alt: Updates kommen oft.",
	["La venta se detuvo: vendiste %d de %d."] = "Verkauf gestoppt: %d von %d verkauft.",
	["La ventana"] = "Das Fenster",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "Er wirkt Feuerbälle und Feuer um sich herum: Unterbrich ihn und halte Abstand, wenn du auf Distanz kämpfst.",
	["Lanza bombas de humo que aturden: sal del humo."] = "Er wirft Rauchbomben, die betäuben: Raus aus dem Rauch.",
	["Lanza con una tecla y recoge con la misma, con autobotín, sonido amplificado y doble clic."] = "Mit einer Taste auswerfen und mit derselben einholen, mit automatischem Plündern, verstärktem Ton und Doppelklick.",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "Er wirkt Ranken, die alle in seiner Nähe umwerfen: Wenn du auf Distanz kämpfst, bleib weg.",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "Er schleudert Feuer um sich: Wenn du auf Distanz kämpfst, halte dich von ihm fern.",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "Er wirkt Erdzauber und stellt Totems auf: Zerstört zuerst die Totems.",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "Er wirft geschmolzenes Metall: Wenn du nicht tankst, stell dich nicht direkt neben ihn.",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "Sie wirkt Blitze und kann sich heilen: Unterbrich ihre Zauber.",
	["Lanza ráfagas arcanas: interrúmpelo."] = "Er wirkt arkane Explosionen: Unterbrich ihn.",
	["Lanza sombras: interrúmpelo."] = "Er wirkt Schattenzauber: Unterbrich ihn.",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "Er verschießt Netze und wirkt einen Fluch: Entferne den Fluch, wenn du kannst.",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "Er erzeugt Sandstürme, die durch den Raum ziehen: Stell dich nicht hinein.",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "Wirk deinen stärksten Zauber aus der Ferne und erledige mit den Spontanzaubern.",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "Wirk zuerst deinen stärksten Zauber und erledige mit einem Schock.",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "Sie speit eine Giftwolke nach vorn: Dreh sie von der Gruppe weg.",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "Er wirft ein Netz, das einen Spieler festhält: Nicht schlimm, greif weiter an.",
	["Lanza veneno a todos: quita el veneno si puedes."] = "Er vergiftet alle: Entferne das Gift, wenn du kannst.",
	["Las cuentas"] = "Die Rechnung",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "Testaccounts können nicht teilen: Das Spiel erlaubt es nicht.",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "Beide steigen von selbst, während du tötest und reist, und was du sammelst, verkauft sich gut: Gold für dein Reittier und deine Fähigkeiten.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "Die Zeilen, die „Ansagen“ in den Chat deiner Gruppe oder deines Schlachtzugs schreibt.",
	["Las marca con una flecha."] = "Upgrades bekommen einen Pfeil.",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "Die Markierungen des Rudels auch auf der Minikarte, nicht nur auf der Weltkarte.",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "Die besten Quests in deiner Nähe, die du schon annehmen kannst, in der kürzesten Reihenfolge.",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "Die vorherigen Quests und die nötige Stufe, damit du sie annehmen kannst.",
	["Las misiones que más experiencia dan cerca de ti."] = "Die Quests in deiner Nähe, die die meiste Erfahrung geben.",
	["Las plantas de herboristería."] = "Pflanzen für Kräuterkunde.",
	["Las que se hacen una sola vez."] = "Die, die man nur einmal macht.",
	["Las que se repiten cada día."] = "Die, die sich jeden Tag wiederholen.",
	["Las que se repiten cada semana."] = "Die, die sich jede Woche wiederholen.",
	["Las que vienen después, más pequeñas a la derecha."] = "Die folgenden, kleiner, rechts daneben.",
	["Las que ya hiciste no cuentan."] = "Bereits erledigte Quests zählen nicht.",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "Die Routen und Pläne, die du auf Alfas Seite Route erstellst.",
	["Las sesiones guardadas de este personaje."] = "Die gespeicherten Sitzungen dieses Charakters.",
	["Las sesiones, las zonas y los objetos de este personaje."] = "Die Sitzungen, Gebiete und Gegenstände dieses Charakters.",
	["Lavanda"] = "Lavendel",
	["Lee el precio más bajo de cada objeto en toda la subasta. No compra ni publica nada. Se puede usar cada 15 minutos."] = "Liest den niedrigsten Preis jedes Gegenstands im ganzen Auktionshaus. Kauft und stellt nichts ein. Alle 15 Minuten nutzbar.",
	["Legendario"] = "Legendär",
	["Lejos de aquí"] = "Weit weg",
	["Lejos de aquí: %s"] = "Weit weg: %s",
	["Letras grandes en el centro de la pantalla cuando el jefe hace algo importante."] = "Große Schrift in der Bildschirmmitte, wenn der Boss etwas Wichtiges tut.",
	["Leyendo precios... %d%%"] = "Lese Preise... %d%%",
	["Leyendo tus bolsas…"] = "Deine Taschen werden gelesen…",
	["Libera tu sello en el enemigo: daño extra."] = "Entfessle dein Siegel auf den Gegner: zusätzlicher Schaden.",
	["Liberar misiones"] = "Questlog aufräumen",
	["Libre: %d de %d"] = "Frei: %d von %d",
	["Libro"] = "Buch",
	["Ligado: no se subasta"] = "Gebunden: nicht versteigerbar",
	["Limpien a sus ayudantes antes de empezar con él."] = "Räumt seine Helfer weg, bevor ihr ihn angreift.",
	["Lista"] = "Bereit",
	["Lista de pasos"] = "Schrittliste",
	["Lista para entrar"] = "Bereit zum Betreten",
	["Lista para entregar"] = "Bereit zur Abgabe",
	["Listas"] = "Bereit",
	["Listas para entregar"] = "Bereit zur Abgabe",
	["Listo"] = "Fertig",
	["Listo para ayudar a tu grupo"] = "Bereit, deiner Gruppe zu helfen",
	["Listo para curar"] = "Bereit zum Heilen",
	["Listo para pescar"] = "Bereit zum Angeln",
	["Listo, fijarlos"] = "Fertig, fixieren",
	["Listo: aprendiste %d rangos de talento"] = "Fertig: Du hast %d Talentränge gelernt",
	["Listo: aprendiste 1 rango de talento"] = "Fertig: Du hast 1 Talentrang gelernt",
	["Listo: te abrimos un susurro para %s. Revisa el mensaje y pulsa Intro."] = "Fertig: Wir haben ein Flüstern an %s geöffnet. Prüf die Nachricht und drück Enter.",
	["Listo: tu mapa también funciona en los marcos de Blizzard."] = "Fertig: Deine Belegung funktioniert auch in Blizzards Rahmen.",
	["Llama a varios lobos al empezar: usen ataques en área o maten primero a los lobos."] = "Zu Beginn ruft er mehrere Wölfe: Nutzt Flächenangriffe oder tötet zuerst die Wölfe.",
	["Llave"] = "Schlüssel",
	["Llavero"] = "Schlüsselbund",
	["Llaves"] = "Schlüssel",
	["Llega a nivel %d"] = "Erreiche Stufe %d",
	["Llega con ayudantes naga: mátenlos primero."] = "Sie kommt mit Naga-Helfern: Tötet sie zuerst.",
	["Llega con guardias: tírenlos aparte si pueden."] = "Er kommt mit Wachen: Zieht sie von ihm weg, wenn ihr könnt.",
	["Llega con lobos: elimínenlos primero."] = "Er kommt mit Wölfen: Erledigt sie zuerst.",
	["Llega con su perro: una persona debe tanquear a cada uno, o maten al perro primero."] = "Er bringt seinen Hund mit: Je eine Person tankt einen, oder tötet zuerst den Hund.",
	["Llega en el nivel %d"] = "Kommt auf Stufe %d",
	["Llegas al rival con ira para pegar de inmediato."] = "Du erreichst den Gegner mit Wut, um sofort zuzuschlagen.",
	["Llegaste al final; quedaron %d pasos sin hacer."] = "Du hast das Ende erreicht; %d Schritte blieben offen.",
	["Llegaste con %s."] = "Du hast %s erreicht.",
	["Lleva al máximo la distancia de la cámara (la de Opciones > Controles). Al apagarlo vuelve la que tenías."] = "Stellt den Kameraabstand (den unter Optionen > Steuerung) aufs Maximum. Beim Ausschalten kommt deiner zurück.",
	["Lleva siempre un sello puesto aunque estés curando."] = "Halte immer ein Siegel aktiv, auch wenn du heilst.",
	["Lleva siempre vendas y comida: descansar poco y seguro es más rápido que morir."] = "Hab immer Verbände und Essen dabei: Kurz und sicher rasten ist schneller als sterben.",
	["Llevas %d de %d pasos. El rastreador te dice el siguiente y la flecha te lleva."] = "%d von %d Schritten geschafft. Der Tracker sagt dir den nächsten, und der Pfeil führt dich hin.",
	["Llorar"] = "Weinen",
	["Llámala antes de pelear."] = "Ruf es vor dem Kampf.",
	["Llévame"] = "Bring mich hin",
	["Llévame a la entrada"] = "Bring mich zum Eingang",
	["Llévame a la subasta"] = "Bring mich zum Auktionshaus",
	["Llévame a reparar"] = "Bring mich zum Reparieren",
	["Llévame a un vendedor"] = "Bring mich zu einem Händler",
	["Llévame al banco"] = "Bring mich zur Bank",
	["Llévame al comerciante"] = "Bring mich zu einem Händler",
	["Llévame con mi entrenador"] = "Bring mich zu meinem Lehrer",
	["Lo acompañan otros lanzadores: interrúmpanlos."] = "Andere Zauberwirker begleiten ihn: Unterbrecht sie.",
	["Lo alto de cada compañero."] = "Wie hoch jedes Mitglied ist.",
	["Lo ancho de cada compañero."] = "Wie breit jedes Mitglied ist.",
	["Lo cambias cuando quieras en Ajustes > Estilo y sonido."] = "Ändere es jederzeit unter Einstellungen > Stil und Klang.",
	["Lo demás, de un vistazo"] = "Der Rest auf einen Blick",
	["Lo enseña un instructor de la profesión"] = "Wird von einem Berufslehrer gelehrt",
	["Lo enseña un instructor en %s"] = "Wird von einem Lehrer in %s gelehrt",
	["Lo esencial"] = "Das Wichtigste",
	["Lo estás siguiendo"] = "Du folgst ihm",
	["Lo estás siguiendo."] = "Du folgst der Person.",
	["Lo gris y lo que marcaste como chatarra. Nunca lo que marcaste para conservar ni lo que pide una misión."] = "Graue Gegenstände und was du als Plunder markiert hast. Nie, was du zum Behalten markiert hast oder was eine Quest braucht.",
	["Lo justo para abrir la siguiente fila."] = "Gerade genug, um die nächste Reihe zu öffnen.",
	["Lo marca como tu objetivo"] = "Macht es zu deinem Ziel",
	["Lo mejor de los dos lados. Si no sabes cuál elegir, elige este."] = "Das Beste aus beiden Seiten. Wenn du nicht weißt, was du wählen sollst, nimm diesen.",
	["Lo mejor para ti"] = "Das Beste für dich",
	["Lo mejor para tu nivel"] = "Das Beste für deine Stufe",
	["Lo más cerca"] = "Am nächsten",
	["Lo más cerca de ti"] = "Am nächsten bei dir",
	["Lo más parecido"] = "Am ähnlichsten",
	["Lo nuevo de esta versión, en pocas palabras."] = "Was diese Version bringt, in wenigen Worten.",
	["Lo nuevo en Alfa %s"] = "Neu in Alfa %s",
	["Lo nuevo en Alfa 1.0"] = "Neu in Alfa 1.0",
	["Lo nuevo y tu Alfa a tu medida"] = "Neuerungen und dein Alfa nach Maß",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, marcos, cuadro de información, probador, cámara y sonidos."] = "Die kleinen Dinge, die das Spiel bequemer machen: Quests, Flüge, Minikarte, Rahmen, Tooltip, Anprobe, Kamera und Sounds.",
	["Lo pescado en esta sesión"] = "In dieser Sitzung geangelt",
	["Lo piden estas misiones"] = "Quests, die es verlangen",
	["Lo pones al empezar a pelear."] = "Du setzt es zu Kampfbeginn ein.",
	["Lo que buscas en la Enciclopedia"] = "Was du in der Enzyklopädie nachschlägst",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "Was jemand aus deiner Gruppe mit Alfa teilt, landet mit seinem Namen in deinen Markierungen, und du bekommst Bescheid, um ihm zu folgen.",
	["Lo que conoce Alfa"] = "Was Alfa kennt",
	["Lo que da"] = "Was es liefert",
	["Lo que encuentras en la manada"] = "Was dich im Rudel erwartet",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "Was dieser Charakter in Dungeons geschafft hat: wird von selbst gespeichert, wenn du Bosse besiegst und Beute aufhebst.",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "Was du beim letzten Spielen mit diesem Charakter erreicht hast.",
	["Lo que hay dentro"] = "Was drin ist",
	["Lo que llevas"] = "Was du trägst",
	["Lo que me sirve"] = "Was mir nützt",
	["Lo que menos vale: %s"] = "Am wenigsten wert: %s",
	["Lo que más conviene ahora"] = "Was sich jetzt am meisten lohnt",
	["Lo que obtuviste en esta sesión"] = "Was du in dieser Sitzung bekommen hast",
	["Lo que pide %s antes, en orden."] = "Was %s zuerst braucht, in Reihenfolge.",
	["Lo que saques aparece aquí, con cuántos llevas de cada uno."] = "Was du fängst, erscheint hier, mit der Anzahl von jedem.",
	["Lo que se pesca aquí"] = "Was man hier angelt",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "Was das Auktionshaus von jedem Verkauf einbehält. Meist 5 % beim Auktionshaus deiner Fraktion und 15 % beim neutralen. Ein Schätzwert.",
	["Lo que sigue en tu build no está en tu árbol"] = "Was als Nächstes in deinem Build kommt, ist nicht in deinem Baum",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "Was als Nächstes kommt, braucht diese Stufe: Bis dahin schickt dich der Guide nicht dorthin.",
	["Lo que sugiere Alfa"] = "Was Alfa vorschlägt",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "Was dein Build von deiner Ausrüstung braucht und wo du es bekommst.",
	["Lo que tu clase se pone antes de pelear está activo."] = "Der Buff, den deine Klasse vor dem Kampf nutzt, ist aktiv.",
	["Lo que tu profesión de recolección junta mejor."] = "Was dein Sammelberuf am besten sammelt.",
	["Lo que ya tienes en el banco"] = "Was du schon in der Bank hast",
	["Lo recolectaste %d veces"] = "Du hast es %d-mal gesammelt",
	["Lo recolectaste 1 vez"] = "Du hast es einmal gesammelt",
	["Lo sueltan"] = "Fallen gelassen von",
	["Lo último que consultaste"] = "Zuletzt nachgeschlagen",
	["Lobo"] = "Wolf",
	["Lobos conectados"] = "Wölfe online",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "NPCs sprechen nicht mehr, wenn sie dich begrüßen oder dir Quests geben. Schaltet auch die Fehlerstimmen stumm.",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "Die Einstellungen der Erinnerungen findest du in der Suche des Alfa-Fensters.",
	["Los botones de otros addons alrededor del minimapa (también el de Alfa) solo aparecen al pasar el ratón por encima."] = "Die Knöpfe anderer Addons um die Minikarte (auch der von Alfa) erscheinen nur, wenn die Maus darüber ist.",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "Die Kreuzzügler des Scharlachroten Kreuzzugs kommen in Gruppen, und einige heilen: Unterbrecht die Heiler.",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "Krits machen doppelten Schaden und geben dem Krieger mehr Wut.",
	["Los datos de Alfa no cargaron (%s)."] = "Alfas Daten wurden nicht geladen (%s).",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "Alfas Daten enthalten keine eigene Beute für seine Bosse.",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "Dungeon-Daten werden außerhalb des Kampfes geladen. Diese Seite füllt sich von selbst, wenn der Kampf vorbei ist.",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "Die Daten stammen vom offiziellen Schadensmesser des Spiels: du, deine Gruppe oder dein Schlachtzug und ihre Begleiter.",
	["Los enemigos de alrededor pegan menos."] = "Gegner um dich herum treffen schwächer.",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "Die Gegner setzen Strahlung und Gift ein: Bringt Heiltränke mit.",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "Die Geomanten wirken Feuer und stellen Totems auf: Unterbrecht sie und zerstört die Totems.",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "Die Goblins in der Gießerei haben Helfer in der Nähe: Schaut euch um, bevor ihr angreift.",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "Optionale und rare Bosse werden entdeckt, wenn du den Dungeon abschließt.",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "Bosse werden entdeckt, wenn du sie besiegst: Name und Beute bleiben bis dahin verborgen. Ihre Tipps kannst du immer ansehen.",
	["Los lobos que usan Alfa y comparten su ubicación, y tu grupo, que ves ahora."] = "Die Wölfe, die Alfa nutzen und ihren Standort teilen, und deine Gruppe, die du gerade siehst.",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "Die Orte, die du aus der Enzyklopädie auf der Karte sehen willst.",
	["Los marcos de Curación están apagados"] = "Die Heilungsrahmen sind aus",
	["Los marcos se mueven fuera de combate."] = "Die Rahmen lassen sich außerhalb des Kampfes verschieben.",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "Die Rahmen, Hintergründe, Knöpfe und Schriften des Spiels, mit goldenen Titeln.",
	["Los mismos marcadores de misiones en el minimapa."] = "Dieselben Questmarkierungen auf der Minikarte.",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "Naga und Satyrn wirken Frost und Blitze: Unterbrecht zuerst die Zauberwirker.",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "Die Vorkommen des Gebiets, das du ansiehst; fahr mit der Maus über eins für Name, Stufe und wie oft du es gesammelt hast. Klick auf eins: Der Pfeil führt dich hin.",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "Vorkommen, die sich auf dem Bildschirm überlappen würden, teilen sich einen Pin mit ihrer Anzahl. Beim Hineinzoomen trennen sie sich.",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "Die Vorkommen in deiner Nähe. Der Suchpunkt des Spiels zeigt, ob gerade etwas da ist.",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Die Vorkommen, die Alfa mitbringt. Ohne diese Option siehst du nur die, die du selbst entdeckt hast.",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "Gegenstände sammeln sich am Ende deiner Taschen statt am Anfang.",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "Die anderen %d Punkte des Plans kommen mit deinen nächsten Stufen.",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "Preise ändern sich: Nach so vielen Tagen erinnert dich Alfa, erneut zu scannen.",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "Wegpunkte, die andere Addons setzen, und der Befehl /way steuern Alfas Pfeil. Ein Addon, das die Einstellungen eines anderen Wegpunkt-Addons erwartet, funktioniert damit eventuell nicht.",
	["Los raros están apagados (página Descubrir)."] = "Rares sind ausgeschaltet (Seite Entdecken).",
	["Los raros también en el minimapa."] = "Rares auch auf der Minikarte.",
	["Los recolectaste %d veces en total"] = "Du hast sie insgesamt %d-mal gesammelt",
	["Los servicios también en el minimapa."] = "Dienste auch auf der Minikarte.",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "Bestätigte Talente lassen sich nicht kostenlos entfernen: Prüf die Liste, bevor du annimmst.",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "Die nächsten Talente des Plans sind nicht in deinem Baum oder können noch nicht genommen werden. Verteile sie von Hand im Talentfenster des Spiels oder wähle einen anderen Build.",
	["Los tesoros también en el minimapa."] = "Schätze auch auf der Minikarte.",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "Troggs fliehen bei wenig Gesundheit und holen Freunde: Haltet sie auf, bevor sie entkommen.",
	["Los últimos puntos."] = "Die letzten Punkte.",
