	["Muéstrala u ocúltala. También con su tecla o con /alfa guia."] = "Ein- oder ausblenden. Auch mit seiner Taste oder mit /alfa guia.",
	["Muñecas"] = "Handgelenke",
	["Más"] = "Mehr",
	["Más Abrumar gracias a Desgarrar."] = "Mehr Überwältigen dank Verwunden.",
	["Más Golpes heroicos: más daño por pelea."] = "Mehr Heldenhafte Stöße: mehr Schaden pro Kampf.",
	["Más adelante"] = "Später",
	["Más aguante y seguridad. Matas un poco más lento, pero casi no mueres."] = "Mehr Ausdauer und Sicherheit. Du tötest etwas langsamer, stirbst aber fast nie.",
	["Más amenaza."] = "Mehr Bedrohung.",
	["Más amenaza: los monstruos se quedan contigo."] = "Mehr Bedrohung: Die Monster bleiben bei dir.",
	["Más crítico en Abrumar, ideal contra pícaros que esquivan."] = "Mehr Krit bei Überwältigen, ideal gegen Schurken, die ausweichen.",
	["Más crítico."] = "Mehr Krit.",
	["Más daño con dos manos."] = "Mehr Schaden mit Zweihandwaffen.",
	["Más daño con el tiempo."] = "Mehr Schaden über Zeit.",
	["Más daño con escudo."] = "Mehr Schaden mit Schild.",
	["Más daño con escudo: lo que hace que Protección suba bien."] = "Mehr Schaden mit Schild: Dadurch levelt Schutz gut.",
	["Más daño con tu arma de dos manos, que es la que usas."] = "Mehr Schaden mit deiner Zweihandwaffe, die du ja nutzt.",
	["Más daño con tu arma de dos manos."] = "Mehr Schaden mit deiner Zweihandwaffe.",
	["Más daño de sangrado; abre Heridas profundas."] = "Mehr Blutungsschaden; öffnet Tiefe Wunden.",
	["Más daño mientras llevas escudo."] = "Mehr Schaden, solange du einen Schild trägst.",
	["Más daño y más riesgo. Matas rápido, pero un error se paga caro."] = "Mehr Schaden und mehr Risiko. Du tötest schnell, aber ein Fehler kostet dich teuer.",
	["Más defensa desde el principio."] = "Mehr Verteidigung von Anfang an.",
	["Más defensa: te golpean y te hacen crítico menos seguido."] = "Mehr Verteidigung: Du wirst seltener getroffen und seltener kritisch getroffen.",
	["Más defensa: te hacen menos críticos."] = "Mehr Verteidigung: Du erleidest weniger Krits.",
	["Más espacio en el banco"] = "Mehr Bankplatz",
	["Más golpe crítico para todo lo que haces."] = "Mehr kritische Treffer für alles, was du tust.",
	["Más golpe crítico, que también te da más ira."] = "Mehr kritische Treffer, die dir auch mehr Wut geben.",
	["Más golpe crítico."] = "Mehr kritische Treffer.",
	["Más golpes bloqueados con el escudo, y cada bloqueo te da ira."] = "Mehr mit dem Schild geblockte Schläge, und jeder Block gibt dir Wut.",
	["Más guías"] = "Mehr Guides",
	["Más ira al cargar."] = "Mehr Wut beim Sturmangriff.",
	["Más ira al cargar: tu primer golpe llega antes."] = "Mehr Wut beim Sturmangriff: Dein erster Schlag kommt früher.",
