	["Más ira por cada golpe, sobre todo con armas rápidas."] = "Mehr Wut pro Schlag, vor allem mit schnellen Waffen.",
	["Más ira por cada golpe: más Golpe heroico y Golpe mortal."] = "Mehr Wut pro Schlag: mehr Heldenhafter Stoß und Tödlicher Stoß.",
	["Más ira por golpe."] = "Mehr Wut pro Schlag.",
	["Más ira por golpe: más habilidades seguidas."] = "Mehr Wut pro Schlag: mehr Fähigkeiten hintereinander.",
	["Más maná y algo de crítico con hechizos."] = "Mehr Mana und etwas Zauberkrit.",
