	["Más velocidad de ataque: mantenlo puesto."] = "Mehr Angriffstempo: Halte es aufrecht.",
	["Más vida: aguantas más golpes antes de tener que comer o descansar."] = "Mehr Gesundheit: Du steckst mehr Schläge ein, bevor du essen oder rasten musst.",
	["Músculos"] = "Muskeln",
	["Nada de esto le sirve a tu clase"] = "Nichts davon passt zu deiner Klasse",
