	["Nada que aplicar"] = "Nichts anzuwenden",
	["Nada que entregar todavía"] = "Noch nichts abzugeben",
	["Nada que recoger"] = "Nichts anzunehmen",
	["Nada que reparar"] = "Nichts zu reparieren",
	["Nada que vender por ahora: lo que llevas sirve o vale más guardado."] = "Gerade nichts zu verkaufen: Was du trägst, ist nützlich oder aufbewahrt mehr wert.",
	["Nadie a la vista tiene ubicación ahora: en una instancia o desconectados. Cuando vuelvan al mundo, aparecen aquí y en tu mapa."] = "Niemand in Sicht hat gerade einen Standort: in einer Instanz oder offline. Wenn sie wieder in der Welt sind, erscheinen sie hier und auf deiner Karte.",
	["Nadie de La Jauría ve dónde estás. Si cambias de idea, lo enciendes en la página de La Jauría."] = "Niemand von La Jauría sieht, wo du bist. Wenn du es dir anders überlegst, schalte es auf der Seite von La Jauría ein.",
	["Nadie de la manada a la vista"] = "Niemand aus dem Rudel in Sicht",
	["Naranja"] = "Orange",
	["Necesita la base de misiones (página Misiones)."] = "Braucht die Quest-Datenbank (Seite Questen).",
	["Necesitas %s"] = "Du brauchst %s",
