	["No compartes"] = "Du teilst nicht",
	["No compartes tu ubicación"] = "Du teilst deinen Standort nicht",
	["No compartes tu ubicación con La Jauría."] = "Du teilst deinen Standort nicht mit La Jauría.",
	["No conozco la entrada de esta mazmorra"] = "Ich kenne den Eingang dieses Dungeons nicht",
	["No cupieron %d: el banco está lleno. Compra otra casilla o pon una bolsa más grande."] = "%d passten nicht: Die Bank ist voll. Kauf einen weiteren Platz oder steck eine größere Tasche hinein.",
	["No disponible"] = "Nicht verfügbar",
	["No encontramos a \"%s\" en tu grupo ni entre quienes comparten su ubicación."] = "Wir haben „%s“ weder in deiner Gruppe noch unter denen gefunden, die ihren Standort teilen.",
	["No encontramos nada"] = "Nichts gefunden",
	["No encontré cómo llegar a esa misión."] = "Ich habe keinen Weg zu dieser Quest gefunden.",
	["No encontré misiones de clase para ti ahora."] = "Ich habe gerade keine Klassenquests für dich gefunden.",
	["No encontré una mazmorra llamada «%s»."] = "Ich habe keinen Dungeon namens „%s“ gefunden.",
	["No entregué %s: pide materiales de oficio. Entrégala tú si quieres."] = "%s nicht abgegeben: Sie verlangt Handwerkswaren. Gib sie selbst ab, wenn du willst.",
	["No entregué %s: pide oro o monedas. Entrégala tú si quieres."] = "%s nicht abgegeben: Sie verlangt Gold oder Währung. Gib sie selbst ab, wenn du willst.",
	["No es para ti"] = "Nicht für dich",
	["No es para tu clase"] = "Nicht für deine Klasse",
	["No es para tu raza"] = "Nicht für dein Volk",
	["No está en tu árbol"] = "Nicht in deinem Baum",
	["No están en tu árbol y se saltan: %s."] = "Nicht in deinem Baum, übersprungen: %s.",
	["No estás siguiendo a nadie."] = "Du folgst niemandem.",
	["No hay guías así"] = "Keine solchen Guides",
	["No hay misiones para ti cerca de aquí. Prueba en el pueblo más cercano o sigue tu ruta."] = "Hier in der Nähe gibt es keine Quests für dich. Versuch es im nächsten Ort oder folge deiner Route.",
	["No hay misiones que convenga dejar"] = "Keine Quests, die sich abzubrechen lohnen",
	["No hay misiones que puedas tomar ahora: te llevo a la entrada."] = "Gerade keine Quest, die du annehmen kannst: Ich bringe dich zum Eingang.",
	["No hay nada que comprar: o ya tienes todo lo del plan hasta tu nivel, o no tienes puntos libres."] = "Es gibt nichts zu kaufen: Entweder hast du schon alles aus dem Plan bis zu deiner Stufe, oder du hast keine freien Punkte.",
	["No hay nodos conocidos en esta zona."] = "Keine bekannten Vorkommen in diesem Gebiet.",
	["No hay un build exacto para %s y %s: este es el que más se parece."] = "Es gibt keinen genauen Build für %s und %s: Das ist der ähnlichste.",
	["No hay un camino que Alfa pueda guiar para esto."] = "Hierfür gibt es keinen Weg, den Alfa führen kann.",
	["No la agregué"] = "Ich habe sie nicht hinzugefügt",
	["No la usas"] = "Nicht benötigt",
	["No llevas chatarra para vender."] = "Du hast keinen Plunder zum Verkaufen.",
	["No llevas nada para depositar con esa opción."] = "Du hast nichts, was mit dieser Option eingelagert wird.",
	["No llevas nada que convenga vender: guarda algo en el banco."] = "Nichts, was sich zu verkaufen lohnt: Lagere etwas in der Bank ein.",
	["No llevas nada que depositar"] = "Nichts zum Einlagern",
	["No lo puedes usar todavía"] = "Du kannst es noch nicht benutzen",
	["No mostrar"] = "Nicht zeigen",
	["No muestra los ataques que todavía tardan mucho: la barra queda más limpia."] = "Blendet Angriffe aus, die noch lange dauern: Die Leiste bleibt übersichtlicher.",
	["No muestra los ataques que ya deberían haber llegado y esperan su momento."] = "Blendet Angriffe aus, die eigentlich schon fällig sind und auf ihren Moment warten.",
	["No pegaste nada."] = "Du hast nichts eingefügt.",
	["No pude armar esa guía"] = "Ich konnte diesen Guide nicht erstellen",
	["No pude armar la ruta"] = "Ich konnte die Route nicht erstellen",
	["No pude leer dónde estás."] = "Ich konnte nicht lesen, wo du bist.",
	["No pude preparar la ruta"] = "Ich konnte die Route nicht vorbereiten",
	["No pudimos unirnos al canal de la manada"] = "Wir konnten dem Kanal des Rudels nicht beitreten",
	["No quedan puntos libres."] = "Keine freien Punkte mehr.",
	["No resaltarlo"] = "Nicht hervorheben",
	["No sabemos dónde está %s. Solo se puede seguir a tu grupo y a quien comparte su ubicación con Alfa."] = "Wir wissen nicht, wo %s ist. Folgen kannst du nur deiner Gruppe und denen, die ihren Standort mit Alfa teilen.",
	["No se aplicaron los talentos"] = "Die Talente wurden nicht angewendet",
	["No se conoce de dónde sale."] = "Herkunft unbekannt.",
	["No se conoce ningún Alfa más reciente. La app de CurseForge o la página de versiones lo dicen con seguridad."] = "Kein neueres Alfa bekannt. Die CurseForge-App oder die Releases-Seite wissen es sicher.",
	["No se conoce su botín"] = "Seine Beute ist unbekannt",
	["No se encontró el chat."] = "Der Chat wurde nicht gefunden.",
	["No se encontró la carpeta Alfa_Codex. Reinstala Alfa completo."] = "Der Ordner Alfa_Codex wurde nicht gefunden. Installiere Alfa komplett neu.",
	["No se encontró nada mejor cerca de tu nivel. Vuelve a buscar al subir unos niveles."] = "Nahe deiner Stufe wurde nichts Besseres gefunden. Such nach ein paar Stufen erneut.",
	["No se pudieron leer los datos del juego."] = "Die Spieldaten konnten nicht gelesen werden.",
	["No se pudo"] = "Hat nicht geklappt",
	["No se pudo abrir el Codex de Alfa (la base de objetos). Revisa que el addon Alfa Codex esté activado."] = "Alfas Codex (die Gegenstandsdatenbank) konnte nicht geöffnet werden. Prüf, ob das Addon Alfa Codex aktiviert ist.",
	["No se pudo armar la guía (%s)."] = "Der Guide konnte nicht erstellt werden (%s).",
	["No se pudo buscar el lugar más cercano."] = "Der nächste Ort konnte nicht gesucht werden.",
	["No se pudo comprar: %s"] = "Kauf nicht möglich: %s",
	["No se pudo leer el escaneo. Intenta de nuevo más tarde."] = "Der Scan konnte nicht gelesen werden. Versuch es später erneut.",
	["No se pudo marcar: falta el motor de Alfa."] = "Markieren nicht möglich: Alfas Kern fehlt.",
	["No se pudo probar ahora"] = "Test gerade nicht möglich",
	["No se puede dibujar el mapa continuo. El mapa del juego sigue funcionando con todas las capas de Alfa."] = "Die durchgehende Karte kann nicht gezeichnet werden. Die Spielkarte funktioniert weiter mit allen Ebenen von Alfa.",
	["No se puede en combate."] = "Nicht im Kampf.",
	["No se puede ordenar en combate."] = "Im Kampf kann nicht sortiert werden.",
	["No se puede vender."] = "Kann nicht verkauft werden.",
	["No se pueden cambiar bolsas en combate."] = "Im Kampf kannst du keine Taschen wechseln.",
	["No se sabe en qué lugar está."] = "Fundort unbekannt.",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "Er erscheint nicht immer in der Mine: Wenn du ihn siehst, ist er ein zusätzlicher Boss mit guter Beute.",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "Nicht immer da. Er wirkt einen Schattenschmerz: Heile alle, die ihn haben.",
	["No sigues ninguna guía"] = "Du folgst keinem Guide",
	["No son para ti"] = "Nicht für dich",
	["No sé de dónde sale este objeto."] = "Ich weiß nicht, woher dieser Gegenstand kommt.",
	["No sé dónde se entrega"] = "Abgabeort unbekannt",
	["No sé dónde se entrega %s: la saqué de la ruta."] = "Ich weiß nicht, wo %s abgegeben wird: Ich habe sie aus der Route genommen.",
	["No sé dónde se entrega %s: la saqué del plan."] = "Ich weiß nicht, wo %s abgegeben wird: Ich habe sie aus dem Plan genommen.",
	["No sé dónde se junta este material."] = "Ich weiß nicht, wo man dieses Material sammelt.",
	["No sé dónde se junta: búscalo en la Enciclopedia para ver de dónde sale."] = "Ich weiß nicht, wo man es sammelt: Schlag es in der Enzyklopädie nach, um zu sehen, woher es kommt.",
	["No sé en qué zona estás."] = "Ich weiß nicht, in welchem Gebiet du bist.",
	["No sé qué misión es."] = "Ich weiß nicht, welche Quest das ist.",
