	["Ocultar los grifos de la barra de acción"] = "Greifen der Aktionsleiste ausblenden",
	["Ocultar los marcos de grupo de Blizzard"] = "Gruppenrahmen von Blizzard ausblenden",
	["Ocultar nombres al pescar"] = "Namen beim Angeln ausblenden",
	["Ocultarlo en combate"] = "Im Kampf ausblenden",
	["Ocultas"] = "Verborgen",
	["Ocultas como en el juego, reveladas, o reveladas con un tono más frío para saber dónde no has estado."] = "Verborgen wie im Spiel, aufgedeckt oder aufgedeckt mit kühlerem Farbton, damit du weißt, wo du noch nicht warst.",
	["Oculto en el modelo."] = "Am Modell ausgeblendet.",
	["Oficiales: %s"] = "Offiziere: %s",
	["Oficios"] = "Berufe",
	["Ojo con tu plan"] = "Achtung bei deinem Plan",
	["Ojo con tu ruta"] = "Achtung bei deiner Route",
	["Ojo: tu clic para lanzar de Blizzard usa %d de estas teclas, y ese manda también aquí. Para igualarlos, usa «Usar también en los marcos de Blizzard»."] = "Achtung: Blizzards Klickzauber nutzt %d dieser Klicks und hat auch hier Vorrang. Um sie anzugleichen, nutze „Auch in Blizzards Rahmen nutzen“.",
	["Olvidar"] = "Vergessen",
	["Olvidar mi progreso aquí"] = "Meinen Fortschritt hier vergessen",
	["Omite este paso: la guía sigue con el siguiente. Puedes volver a él con Anterior."] = "Überspringt diesen Schritt: Der Guide macht mit dem nächsten weiter. Mit „Vorheriger“ kommst du zu ihm zurück.",
	["Omitir"] = "Überspringen",
	["Omitir esta meta"] = "Dieses Ziel überspringen",
	["Omitir esta misión"] = "Diese Quest überspringen",
	["Omitirla"] = "Überspringen",
	["Opacidad de la ventana"] = "Deckkraft des Fensters",
	["Opacidad fuera de combate"] = "Deckkraft außerhalb des Kampfes",
