	["Opciones de Mundo"] = "Welt-Optionen",
	["Orcos"] = "Orcs",
	["Orden"] = "Reihenfolge",
	["Ordenar"] = "Sortieren",
	["Ordenar de derecha a izquierda"] = "Von rechts nach links sortieren",
	["Oro"] = "Gold",
	["Oro de hoy"] = "Gold heute",
	["Oro neto por sesión"] = "Gold netto pro Sitzung",
	["Otras opciones"] = "Weitere Optionen",
	["Otro addon de bolsas está activo"] = "Ein anderes Taschen-Addon ist aktiv",
	["Otro addon de pesca está activo"] = "Ein anderes Angel-Addon ist aktiv",
	["Otro addon de pesca está activo. Para que no choquen, la pesca de Alfa queda en pausa: desactiva uno de los dos en la lista de addons."] = "Ein anderes Angel-Addon ist aktiv. Damit sie sich nicht in die Quere kommen, pausiert Alfas Angeln: Deaktiviere eines der beiden in der AddOn-Liste.",
	["Otro golpe fuerte para tu rotación."] = "Ein weiterer starker Schlag für deine Rotation.",
	["Otro golpe fuerte."] = "Ein weiterer starker Schlag.",
	["Otros"] = "Sonstiges",
	["Otros addons pueden poner puntos de ruta"] = "Andere Addons dürfen Wegpunkte setzen",
	["Otros caminos"] = "Andere Wege",
	["PNJ"] = "NPCs",
	["PNJ %d"] = "NPC %d",
	["Paladín"] = "Paladin",
	["Panel de estadísticas"] = "Werte-Panel",
	["Para abandonar"] = "Zum Abbrechen",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "Um sie mit der Kartentaste zu öffnen, schalte unten „Alfas Karte mit der Kartentaste öffnen“ ein.",
	["Para alguien de tu hermandad, agrega su rango."] = "Zeigt bei Mitgliedern deiner Gilde ihren Rang.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Für jeden Gegenstand vergleicht Alfa drei Wege: an den Händler verkaufen, im Auktionshaus einstellen oder umwandeln (mit einem Rezept, das du kennst, oder durch Entzaubern).",
	["Para comprar espacio, habla con un banquero."] = "Um Platz zu kaufen, sprich mit einem Bankier.",
	["Para conservar"] = "Zum Behalten",
	["Para depositar, habla con un banquero."] = "Zum Einlagern sprich mit einem Bankier.",
	["Para empezar"] = "Zum Start",
	["Para entregar"] = "Zum Abgeben",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "Für deine Wahl gibt es keinen mit diesem Stil: Alfa nutzt den ähnlichsten.",
	["Para mi nivel (±3)"] = "Für meine Stufe (±3)",
	["Para mí"] = "Für mich",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "Damit es keine Konflikte gibt, ersetzt Alfa deine Taschen nicht, solange es aktiv ist. Alfas Fenster kannst du trotzdem von hier öffnen.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "Damit du deine Gruppe nicht doppelt siehst. Änderung außerhalb des Kampfes.",
	["Para pescar necesitas una caña en las manos. Cuando la tengas puesta, ya puedes lanzar."] = "Zum Angeln brauchst du eine Angelrute in der Hand. Sobald sie angelegt ist, kannst du auswerfen.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "Damit sie sich nicht in die Quere kommen, übernimmt Alfa weder deine Taste noch ändert es deine Einstellungen. Deaktiviere eines der beiden in der AddOn-Liste (Charakterauswahl) und lade neu. Behältst du Alfa, übernimmt es von selbst die Taste, die du im anderen Addon benutzt hast.",
	["Para que no dejes botín tirado por falta de espacio."] = "Damit du keine Beute aus Platzmangel liegen lässt.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "Für alle, die lieber mit Linksklick anvisieren: Die Heilung dieses Klicks wandert auf die mittlere Taste. Deine Voreinstellung wird erneut angewendet.",
	["Para recoger ahora"] = "Jetzt zum Annehmen",
	["Para subir de nivel"] = "Bis zum Stufenaufstieg",
	["Para ti"] = "Für dich",
	["Para tu %s"] = "Als %s",
	["Para tu nivel"] = "Für deine Stufe",
	["Para tu nivel (%d)"] = "Für deine Stufe (%d)",
	["Para tu nivel ahora"] = "Jetzt für deine Stufe",
	["Para vender"] = "Zum Verkaufen",
	["Para vender, habla con un comerciante."] = "Zum Verkaufen sprich mit einem Händler.",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "Um ihn wieder aufzuladen, ruh dich in einem Gasthaus oder einer Stadt aus (oder logg dich dort aus).",
	["Parada"] = "Parieren",
	["Parada %d de %d"] = "Halt %d von %d",
	["Parar"] = "Parieren",
	["Paras más golpes de otros guerreros y pícaros."] = "Du parierst mehr Schläge von anderen Kriegern und Schurken.",
	["Paras más golpes."] = "Du parierst mehr Schläge.",
	["Paras más golpes: recibes menos daño desde el principio."] = "Du parierst mehr Schläge: Du nimmst von Anfang an weniger Schaden.",
	["Paras un poco más."] = "Du parierst etwas mehr.",
	["Paraste un golpe: el contraataque está listo."] = "Du hast einen Schlag pariert: Der Gegenangriff ist bereit.",
	["Paraste un golpe: tu contraataque está listo y desarma al enemigo."] = "Du hast einen Schlag pariert: Dein Gegenangriff ist bereit und entwaffnet den Gegner.",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "Du hast einen Schlag pariert: Dein Gegenangriff macht den Gegner bewegungsunfähig.",
	["Pasa el ratón sobre un compañero y cúralo con un clic."] = "Fahr mit der Maus über ein Gruppenmitglied und heile es mit einem Klick.",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "Fahr mit der Maus über ein Gruppenmitglied und klicke – links: %s, rechts: %s.",
	["Pasa enfermedades: quítalas si tu clase puede."] = "Er überträgt Krankheiten: Entferne sie, wenn deine Klasse kann.",
	["Pasa tu build a un amigo o usa el que te pasen."] = "Gib deinen Build an einen Freund weiter oder nutze den, den man dir gibt.",
	["Paso %d"] = "Schritt %d",
	["Paso %d de %d"] = "Schritt %d von %d",
	["Pasos que siguen, numerados"] = "Nächste Schritte, nummeriert",
	["Pausa"] = "Pause",
	["Pecho"] = "Brust",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "Füge hier (Strg+V) den Text einer Alfa-Route ein.",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "Füge hier einen Text ein, der mit ALFA1; beginnt (Strg + V), und drück „Importieren“. Alfa prüft jedes Talent gegen deinen Baum.",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "Er schlägt hart zu, hat aber keine Tricks: ein guter Boss zum Lernen.",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "Er schlägt hart zu und schützt sich mit einem Schild aus Licht: Fang mit voller Gesundheit an.",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "Er schlägt den Tank oft hintereinander: Lass dessen Gesundheit nicht unter die Hälfte fallen.",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "Er schlägt sehr hart zu: Beginn den Kampf mit voller Gesundheit.",
	["Pega primero una cadena de build de Alfa."] = "Füge zuerst einen Alfa-Build-Text ein.",
	["Pega primero una cadena de escala de estadísticas."] = "Füge zuerst einen Werteskala-Text ein.",
	["Pega una cadena de escala de estadísticas (Ctrl+V), la que copiaste desde donde la compartieron."] = "Füge einen Werteskala-Text ein (Strg+V), den du dort kopiert hast, wo er geteilt wurde.",
	["Pega varias veces seguidas: empieza con la vida llena."] = "Er schlägt mehrmals hintereinander zu: Fang mit voller Gesundheit an.",
	["Pegas a dos: útil contra mascotas y grupos."] = "Du triffst zwei: nützlich gegen Begleiter und Gruppen.",
	["Pegas más después de recibir críticos."] = "Du triffst härter, nachdem du Krits erlitten hast.",
	["Pegas más fuerte después de recibir críticos."] = "Du schlägst härter zu, nachdem du Krits erlitten hast.",
	["Pegas más fuerte después de recibir un golpe crítico."] = "Du schlägst härter zu, nachdem du einen kritischen Treffer erlitten hast.",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "Kämpf immer nur gegen ein Monster; wenn zwei kommen, nutze Weitreichende Stöße.",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "Kämpf immer mit voller Gesundheit; reih keine Monster ohne Rast aneinander.",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "Gegen andere Spieler kämpfen: durchhalten, bremsen und erledigen.",
	["Peletería"] = "Lederverarbeitung",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "Lederverarbeitung macht Leder mit Rüstung und Ausdauer für die Bärengestalt.",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "Lederverarbeitung macht Kettenrüstung für dich; Kürschnerei liefert das Material, ohne Gold auszugeben.",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "Lederverarbeitung macht Lederteile mit Beweglichkeit und Ausdauer; Kürschnerei liefert dir das Leder.",
	["Peligro"] = "Gefahr",
	["Peligrosa para tu nivel"] = "Gefährlich für deine Stufe",
	["Pendiente"] = "Ausstehend",
	["Pequeños íconos en cada ataque: si es para el tanque, para quien cura, si se puede quitar o si es mortal."] = "Kleine Symbole an jedem Angriff: ob er für den Tank oder den Heiler ist, ob er sich entfernen lässt oder ob er tödlich ist.",
	["Perdimos el rastro de %s: ya no sabemos dónde está."] = "Wir haben die Spur von %s verloren: Wir wissen nicht mehr, wo die Person ist.",
	["Perjuicios que puedes quitar"] = "Entfernbare Schwächungszauber",
	["Permite lanzar con doble clic aunque vayas montado."] = "Erlaubt das Auswerfen per Doppelklick auch auf einem Reittier.",
	["Personaje"] = "Charakter",
	["Pesca"] = "Angeln",
	["Pesca %d"] = "Angeln %d",
	["Pesca %d / %d"] = "Angeln %d / %d",
	["Pesca de Alfa apagada. Tu tecla y tus ajustes quedan como siempre."] = "Alfas Angeln ist aus. Deine Taste und deine Einstellungen bleiben wie immer.",
	["Pesca de Alfa encendida, pero en pausa mientras otro addon de pesca esté activo."] = "Alfas Angeln ist an, aber pausiert, solange ein anderes Angel-Addon aktiv ist.",
	["Pesca de Alfa encendida."] = "Alfas Angeln ist an.",
	["Pescando"] = "Am Angeln",
	["Pescando…"] = "Am Angeln…",
	["Pescar: lanzar y recoger"] = "Angeln: Auswerfen und Einholen",
	["Pesos de %s activos: las flechas de mejora ya los usan."] = "Gewichtungen von %s aktiv: Die Upgrade-Pfeile nutzen sie schon.",
	["Pestaña nueva"] = "Neuer Tab",
	["Picadura de serpiente: daño con el tiempo."] = "Schlangenbiss: Schaden über Zeit.",
	["Pide al grupo que espere unos segundos antes de atacar."] = "Bitte die Gruppe, ein paar Sekunden zu warten, bevor sie angreift.",
	["Pide grupo"] = "Braucht Gruppe",
	["Pidiendo los precios a la subasta..."] = "Frage Preise beim Auktionshaus an...",
	["Piel o armadura demoníaca"] = "Dämonenhaut oder Dämonenrüstung",
	["Piernas"] = "Beine",
	["Pies"] = "Füße",
	["Pinta del color de la clase el fondo del nombre en tu marco y en el del objetivo cuando es un jugador."] = "Färbt den Namenshintergrund in deinem Rahmen und im Zielrahmen (wenn es ein Spieler ist) in der Klassenfarbe.",
	["Pizarra"] = "Schiefer",
	["Placas"] = "Platte",
	["Plan en marcha"] = "Plan läuft",
	["Plan por nivel"] = "Plan nach Stufe",
	["Plantilla: %s"] = "Vorlage: %s",
	["Pobre"] = "Schlecht",
	["Poco común"] = "Selten",
	["Poco probable (%d)"] = "Unwahrscheinlich (%d)",
	["Pocos"] = "Wenige",
	["Pocos lugares de %s en %s"] = "Wenige Orte für %s in %s",
	["Pocos precios"] = "Wenige Preise",
	["Poder a distancia"] = "Distanzangriffskraft",
	["Poder con hechizos"] = "Zaubermacht",
	["Poder de ataque"] = "Angriffskraft",
	["Poder de ataque a distancia"] = "Distanzangriffskraft",
	["Pon Seccionar en cuanto llegues al rival y mantenlo puesto."] = "Setz Kniesehne, sobald du den Gegner erreichst, und halte sie aktiv.",
	["Pon ahora"] = "Jetzt nehmen",
	["Pon todos tus hechizos de daño en el tiempo y deja que tu demonio aguante."] = "Setz alle deine Zauber mit Schaden über Zeit und lass deinen Dämon das Monster halten.",
	["Pon tu escudo y tu daño en el tiempo antes de que el monstruo llegue."] = "Setz deinen Schild und deinen Schaden über Zeit, bevor das Monster ankommt.",
	["Pon tus tótems al empezar cada pelea grande."] = "Stell zu Beginn jedes großen Kampfes deine Totems auf.",
	["Pon un tótem antes de empezar la pelea."] = "Stell vor dem Kampf ein Totem auf.",
	["Pon una trampa antes de empezar la pelea y lleva al monstruo hacia ella."] = "Leg vor dem Kampf eine Falle und lock das Monster hinein.",
	["Pon venenos en tus armas siempre."] = "Halte immer Gifte auf deinen Waffen.",
	["Pone el enlace en el chat."] = "Setzt den Link in den Chat.",
	["Pone la flecha ahí."] = "Setzt den Pfeil dorthin.",
	["Pone los marcos donde estaban al instalar Alfa."] = "Setzt die Rahmen dorthin zurück, wo sie bei der Installation von Alfa waren.",
	["Pone tres ataques de prueba en la línea de tiempo para que veas dónde sale. Se borran solos. Para moverla: menú del juego (Esc) > Modo de edición."] = "Setzt drei Testangriffe auf die Zeitleiste, damit du siehst, wo sie erscheint. Sie verschwinden von selbst. Zum Verschieben: Spielmenü (Esc) > Bearbeitungsmodus.",
	["Pone una maldición que baja la curación que recibes: quítala si tu clase puede."] = "Er wirkt einen Fluch, der die erhaltene Heilung senkt: Entferne ihn, wenn deine Klasse kann.",
	["Pone una maldición que te debilita y un fuego que quema poco a poco: quita la maldición si puedes."] = "Er wirkt einen schwächenden Fluch und ein Feuer, das nach und nach brennt: Entferne den Fluch, wenn du kannst.",
	["Poner la flecha aquí"] = "Pfeil hierher setzen",
	["Ponlo de espaldas al grupo para que su golpe solo te dé a ti."] = "Dreh ihn mit dem Rücken zur Gruppe, damit sein Schlag nur dich trifft.",
	["Ponlo de espaldas al grupo y aguanta: la pelea es corta."] = "Dreh ihn mit dem Rücken zur Gruppe und halte durch: Der Kampf ist kurz.",
	["Ponlos al empezar a pelear."] = "Stell sie zu Kampfbeginn auf.",
	["Ponte un escudo antes de empezar cada pelea."] = "Wirk vor jedem Kampf einen Schild auf dich.",
	["Por ahora, guárdalo todo"] = "Behalte vorerst alles",
	["Por bolsa"] = "Nach Tasche",
	["Por categorías"] = "Nach Kategorien",
	["Por clase"] = "Nach Klasse",
	["Por debajo de tu nivel"] = "Unter deiner Stufe",
	["Por dónde sale: %s"] = "Wird gesendet über: %s",
	["Por grupo"] = "Nach Gruppe",
	["Por honor (JcJ)"] = "Für Ehre (PvP)",
	["Por hora"] = "Pro Stunde",
	["Por mazmorra"] = "Nach Dungeon",
	["Por nivel: jefes, botín, misiones, la entrada y consejos."] = "Nach Stufe: Bosse, Beute, Quests, der Eingang und Tipps.",
	["Por nombre"] = "Nach Name",
	["Por nombre, tipo o calidad (verde, azul...) y por nivel de objeto: 20, >20, 20-30. Lo que coincide se resalta."] = "Nach Name, Typ oder Qualität (grün, blau...) und nach Gegenstandsstufe: 20, >20, 20-30. Treffer werden hervorgehoben.",
	["Por reputación"] = "Für Ruf",
	["Por rol"] = "Nach Rolle",
	["Por terminar"] = "In Arbeit",
	["Por zona (este personaje)"] = "Nach Gebiet (dieser Charakter)",
	["Porcentaje de vida"] = "Gesundheit in Prozent",
	["Posada"] = "Gasthaus",
	["Posadas"] = "Gasthäuser",
	["Posadero"] = "Gastwirt",
	["Posaderos"] = "Gastwirte",
	["Posaderos; se marca el de tu piedra de hogar."] = "Gastwirte; der deines Ruhesteins ist markiert.",
	["Preajuste «%s» listo para tus clics."] = "Voreinstellung „%s“ ist für deine Klicks bereit.",
	["Preajustes"] = "Voreinstellungen",
	["Preajustes listos para usar"] = "Fertige Voreinstellungen",
	["Precio de %s"] = "Preis laut %s",
	["Precios %s · %s objetos"] = "Preise %s · %s Gegenstände",
	["Precios al día"] = "Preise aktuell",
	["Precios de la subasta"] = "Auktionspreise",
	["Precios viejos"] = "Alte Preise",
	["Precios y qué conviene vender."] = "Preise und was sich zu verkaufen lohnt.",
	["Precisión"] = "Trefferchance",
	["Precisión con hechizos"] = "Zaubertrefferchance",
	["Premio: %s"] = "Belohnung: %s",
	["Prende la línea de tiempo, los íconos de ayuda y los mensajes medianos y graves."] = "Schaltet die Zeitleiste, die Hilfssymbole und die mittleren und kritischen Meldungen ein.",
	["Prende todo el sistema de avisos de jefes de Blizzard: la línea de tiempo y los mensajes en pantalla. Sin esto, lo demás no se ve."] = "Schaltet Blizzards gesamtes System für Boss-Warnungen ein: die Zeitleiste und die Bildschirmmeldungen. Ohne das ist der Rest nicht zu sehen.",
	["Prenderlo"] = "Einschalten",
	["Prepara tus marcos de curación"] = "Richte deine Heilungsrahmen ein",
	["Prepara tus marcos en 3 pasos"] = "Richte deine Rahmen in 3 Schritten ein",
	["Preparando %s… %s"] = "%s wird vorbereitet… %s",
	["Preparando %s… la ficha se completa sola."] = "%s wird vorbereitet… Der Eintrag füllt sich von selbst.",
	["Preparando la enciclopedia…"] = "Enzyklopädie wird vorbereitet…",
	["Preparando lo que contiene… la ficha se completa sola."] = "Inhalt wird vorbereitet… Der Eintrag füllt sich von selbst.",
	["Preparando lo que da… la ficha se completa sola."] = "Ertrag wird vorbereitet… Der Eintrag füllt sich von selbst.",
	["Preparando lo que vende y suelta… la ficha se completa sola."] = "Waren und Beute werden vorbereitet… Der Eintrag füllt sich von selbst.",
	["Prepárame"] = "Mach mich bereit",
	["Prepárate para entrar"] = "Mach dich bereit zum Betreten",
	["Primer aviso"] = "Erste Warnung",
	["Primero cobra lo que ya hiciste: una ruta por el camino más corto, junta por PNJ."] = "Löse zuerst ein, was du schon erledigt hast: eine Route auf dem kürzesten Weg, gebündelt nach NPC.",
	["Primero crea una ruta: /alfa recoleccion ruta"] = "Erstelle zuerst eine Route: /alfa recoleccion ruta",
	["Primero defensa: paras muchos más golpes y descansas menos."] = "Zuerst Verteidigung: Du parierst viel mehr Schläge und rastest weniger.",
	["Primero elige tu build"] = "Wähle zuerst deinen Build",
	["Primero necesitas %s, que se toma a nivel %d."] = "Zuerst brauchst du %s, die man auf Stufe %d annimmt.",
	["Primero pelean contra el Comandante Mograine; cuando cae, ella llega y lo resucita."] = "Zuerst kämpft ihr gegen Kommandant Mograine; wenn er fällt, kommt sie und belebt ihn wieder.",
	["Primero prende la línea de tiempo del jefe."] = "Schalte zuerst die Boss-Zeitleiste ein.",
	["Primero sale su trituradora; al romperla, Sneed baja y pelea a pie."] = "Zuerst kommt sein Schredder; wenn er zerstört ist, springt Sneed heraus und kämpft zu Fuß.",
	["Primero toma %s"] = "Nimm zuerst %s an",
	["Primeros auxilios"] = "Erste Hilfe",
	["Principal"] = "Primär",
	["Probador"] = "Anprobe",
	["Probar"] = "Testen",
	["Probar con 20"] = "Test mit 20",
	["Probar con 5"] = "Test mit 5",
	["Probar la línea de tiempo"] = "Zeitleiste testen",
	["Probar la ventana"] = "Fenster ausprobieren",
	["Probar otra vez"] = "Erneut versuchen",
	["Probar un aviso"] = "Hinweis testen",
	["Profesiones"] = "Berufe",
	["Profesiones que te sirven"] = "Berufe, die dir nützen",
	["Profesión"] = "Beruf",
	["Promedio de la sesión: %s XP por hora."] = "Durchschnitt der Sitzung: %s EP pro Stunde.",
	["Promedio de la sesión: %s XP por hora. XP ganada: %s."] = "Sitzungsschnitt: %s EP pro Stunde. Erhaltene EP: %s.",
	["Protección"] = "Schutz",
	["Protección para subir"] = "Schutz zum Leveln",
	["Proyectiles"] = "Projektile",
	["Prueba"] = "Test",
	["Prueba con %d: arrastra para mover"] = "Test mit %d: zum Verschieben ziehen",
	["Prueba con otra búsqueda o quita un filtro."] = "Versuch eine andere Suche oder entferne einen Filter.",
	["Prueba con otra palabra o elige Todas."] = "Versuch ein anderes Wort oder wähle „Alle“.",
	["Prueba con otra palabra, en español o en inglés, o quita un filtro."] = "Versuch ein anderes Wort, auf Deutsch oder Englisch, oder entferne einen Filter.",
	["Prueba con otra palabra."] = "Versuch ein anderes Wort.",
	["Prueba con otro filtro."] = "Versuch einen anderen Filter.",
	["Prueba de Alfa %d"] = "Alfa-Test %d",
	["Prueba tus clics"] = "Teste deine Klicks",
	["Pruébala fuera de mazmorras y bandas."] = "Teste sie außerhalb von Dungeons und Schlachtzügen.",
	["Préndelo para ver jefes, botín, misiones y consejos de cada mazmorra."] = "Schalte es ein, um Bosse, Beute, Quests und Tipps jedes Dungeons zu sehen.",
	["Puede controlar la mente de un jugador: no lo ataquen, esperen a que se le pase."] = "Er kann den Geist eines Spielers beherrschen: Greift ihn nicht an, wartet, bis es vorbei ist.",
	["Puede convertir a alguien en huargo: no ataquen a ese jugador, se le pasa solo."] = "Er kann jemanden in einen Worgen verwandeln: Greift diesen Spieler nicht an, es vergeht von selbst.",
	["Puede dormir a alguien del grupo: sigue peleando, se despierta solo."] = "Sie kann jemanden aus der Gruppe einschläfern: Kämpf weiter, er wacht von selbst auf.",
	["Puede dormir a alguien y golpear a todos los que están cerca."] = "Er kann jemanden einschläfern und alle in seiner Nähe treffen.",
	["Puede lanzarte por los aires con un gancho: regresa rápido para que no vaya tras quien cura."] = "Er kann dich mit einem Aufwärtshaken durch die Luft schleudern: Lauf schnell zurück, damit er nicht auf den Heiler losgeht.",
	["Puede pisotear a los que pelean cuerpo a cuerpo: mantén su vida alta."] = "Er kann Nahkämpfer niedertrampeln: Halte ihre Gesundheit hoch.",
	["Puedes Cargar en actitud defensiva: empiezas a tanquear sin cambiar de actitud."] = "Du kannst in Verteidigungshaltung Sturmangriff nutzen: Du beginnst zu tanken, ohne die Haltung zu wechseln.",
	["Puedes cambiar cada tramo."] = "Du kannst jede Etappe ändern.",
	["Puedes tomarla"] = "Du kannst sie annehmen",
	["Puedes usarlo"] = "Du kannst es nutzen",
	["Puedes vender %d cosas por unos %s."] = "Du kannst %d Sachen für etwa %s verkaufen.",
	["Puedes vender %s (unos %s)."] = "Du kannst %s verkaufen (etwa %s).",
	["Puedo usar"] = "Kann ich nutzen",
	["Pulsa %s para lanzar. Cuando el corcho se hunda, pulsa %s otra vez para recoger."] = "Drück %s zum Auswerfen. Wenn der Schwimmer abtaucht, drück erneut %s zum Einholen.",
	["Pulsa Guiarme y la flecha te lleva de parada en parada desde la más cercana."] = "Drück „Hinführen“, und der Pfeil führt dich von Halt zu Halt, beginnend beim nächstgelegenen.",
	["Pulsa una tecla…"] = "Drück eine Taste…",
	["Puntería"] = "Treffsicherheit",
	["Puntería para subir"] = "Treffsicherheit zum Leveln",
	["Punto %d de tu build (nivel %d), hasta %d/%d."] = "Punkt %d deines Builds (Stufe %d), bis %d/%d.",
	["Puntos %d a %d de tu build (niveles %d a %d)."] = "Punkte %d bis %d deines Builds (Stufen %d bis %d).",
	["Puntos de ruta"] = "Wegpunkte",
	["Puntos por gastar"] = "Punkte zu verteilen",
	["Página Ruta"] = "Seite Route",
	["Pícaro"] = "Schurke",
	["Queda 1"] = "Noch 1",
	["Queda lejos: unos %s de camino"] = "Weit weg: etwa %s unterwegs",
	["Quedan %d"] = "Noch %d",
	["Quedan %d casillas libres y no llevas nada que convenga vender: guarda algo en el banco."] = "Noch %d freie Plätze und nichts, was sich zu verkaufen lohnt: Lagere etwas in der Bank ein.",
	["Quedan %d casillas libres. Puedes vender %s (unos %s)."] = "Noch %d freie Plätze. Du kannst %s verkaufen (etwa %s).",
	["Quedan %s"] = "Noch %s",
	["Quedó sin pasos: agrega tramos o recalcula."] = "Keine Schritte mehr: Füge Etappen hinzu oder berechne neu.",
	["Quema al enemigo un rato."] = "Verbrennt den Gegner eine Weile.",
	["Quien use Alfa en tu grupo lo recibe y puede seguirlo."] = "Wer in deiner Gruppe Alfa nutzt, erhält sie und kann ihr folgen.",
	["Quienes comparten su ubicación contigo. Un clic en su marca y la flecha te lleva."] = "Wer seinen Standort mit dir teilt. Ein Klick auf die Markierung, und der Pfeil führt dich hin.",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras ni por canales públicos."] = "Wer Alfa nutzt und teilt, sieht dich auf der Karte und kann dir folgen, und du ihnen. Gesendet werden dein Gebiet, deine Position, deine Stufe und deine Klasse, alle 10 Sekunden, während du dich bewegst (alle 4 Minuten, wenn du stillstehst), nie in Dungeons und nie über öffentliche Kanäle.",
	["Quiero"] = "Ich will",
	["Quiero unirme"] = "Ich will beitreten",
	["Quieto"] = "Stehen",
	["Quita los grifos de los lados de la barra principal. Edit Mode también tiene su propia opción para esto."] = "Entfernt die Greifen an den Seiten der Hauptleiste. Edit Mode hat dafür auch eine eigene Option.",
	["Quitar"] = "Entfernen",
	["Quitar de mi plan"] = "Aus meinem Plan entfernen",
	["Quitar de mi plan de misiones"] = "Aus meinem Questplan entfernen",
	["Quitar del mapa"] = "Von der Karte entfernen",
	["Quitar del plan"] = "Aus dem Plan entfernen",
	["Quitar este tramo"] = "Diese Etappe entfernen",
	["Quitar filtros"] = "Filter entfernen",
	["Quitar la prueba"] = "Test beenden",
	["Quién la da"] = "Wer sie vergibt",
	["Quién la da, qué pide, qué te dan y qué necesitas antes."] = "Wer sie vergibt, was sie verlangt, was du bekommst und was du vorher brauchst.",
	["Qué es Alfa"] = "Was Alfa ist",
	["Qué estadísticas buscar"] = "Welche Werte du suchen solltest",
	["Qué estadísticas buscar y lo mejor que puedes usar en tu nivel."] = "Welche Werte du suchen solltest und das Beste, was du auf deiner Stufe nutzen kannst.",
	["Qué habilidad presionar ahora y cuáles siguen, avisos de reacción y el top de daño de tu grupo."] = "Welche Fähigkeit du jetzt drückst und welche folgen, Reaktionshinweise und das Schadens-Top deiner Gruppe.",
	["Qué hace: %s"] = "Was es tut: %s",
	["Qué hacer ahora, tu plan de misiones y tus rutas propias."] = "Was jetzt zu tun ist, dein Questplan und deine eigenen Routen.",
	["Qué hacer con lo que llevas"] = "Was tun mit dem, was du trägst",
	["Qué hay que hacer"] = "Was zu tun ist",
	["Qué me falta"] = "Was mir fehlt",
	["Qué mensajes mostrar"] = "Welche Meldungen zeigen",
	["Qué muestran"] = "Was sie zeigen",
	["Qué presionar y en qué orden, avisos de reacción, la barra de golpe y el medidor de daño."] = "Was du drückst und in welcher Reihenfolge, Reaktionshinweise, die Schlagleiste und der Schadensmesser.",
	["Qué quieres buscar"] = "Was willst du nachschlagen",
	["Qué recolectar"] = "Was sammeln",
	["Qué recolectar, fabricar o vender hoy."] = "Was du heute sammeln, herstellen oder verkaufen kannst.",
	["Qué se pinta en tus mapas"] = "Was auf deinen Karten gezeichnet wird",
	["Qué se ve"] = "Was angezeigt wird",
	["Qué talento poner ahora y por qué, tu build en dos clics, tu árbol y tu equipo."] = "Welches Talent du jetzt nimmst und warum, dein Build in zwei Klicks, dein Baum und deine Ausrüstung.",
	["Qué talento poner y por qué, ayuda de rotación y el daño del grupo."] = "Welches Talent und warum, eine Rotationshilfe und der Schaden deiner Gruppe.",
	["Qué tan difíciles pueden ser las misiones que Alfa elige (siempre de las que ya puedes tomar)."] = "Wie schwer die Quests sein dürfen, die Alfa wählt (immer welche, die du schon annehmen kannst).",
	["Qué tan fuerte se oye el juego mientras el corcho está en el agua."] = "Wie laut das Spiel ist, solange der Schwimmer im Wasser ist.",
	["Qué tan grande se ve cada casilla."] = "Wie groß jeder Platz aussieht.",
	["Qué tanto se ve el ícono mientras no peleas."] = "Wie sichtbar das Symbol ist, während du nicht kämpfst.",
	["Qué vender y qué conservar"] = "Was verkaufen, was behalten",
