	["Recoger misiones cerca"] = "Quests in der Nähe annehmen",
	["Recoger todo lo que pesques"] = "Alles Geangelte plündern",
	["Recoges %d misiones en el camino y te llevo a la entrada."] = "Du nimmst unterwegs %d Quests an, und ich bringe dich zum Eingang.",
	["Recoges 1 misión en el camino y te llevo a la entrada."] = "Du nimmst unterwegs 1 Quest an, und ich bringe dich zum Eingang.",
	["Recoges hierbas por el camino y haces pociones de vida y maná: menos descanso y más seguridad."] = "Du sammelst unterwegs Kräuter und machst Heil- und Manatränke: weniger Rast und mehr Sicherheit.",
