	["Recomendadas para ti"] = "Empfohlen für dich",
	["Recomendado"] = "Empfohlen",
	["Recomendado por Alfa"] = "Von Alfa empfohlen",
	["Recomienda el camino que te deja más oro, si gana por lo menos un 10 % a venderlo. Si nada da oro, te dice que lo guardes. Alfa nunca vende ni compra por ti."] = "Empfiehlt den Weg, der dir am meisten Gold bringt, wenn er mindestens 10 % mehr bringt als der Händler. Bringt nichts Gold, rät es dir zum Behalten. Alfa verkauft oder kauft nie für dich.",
	["Recompensa de misión"] = "Questbelohnung",
	["Recompensas"] = "Belohnungen",
	["Recordatorios"] = "Erinnerungen",
	["Recuperas maná incluso mientras peleas."] = "Du regenerierst Mana sogar im Kampf.",
	["Recuperas vida después de recibir críticos."] = "Du regenerierst Gesundheit, nachdem du Krits erlitten hast.",
	["Recuperas vida después de recibir críticos: descansas menos."] = "Du regenerierst Gesundheit, nachdem du Krits erlitten hast: Du rastest weniger.",
	["Recuperas vida poco a poco, incluso en combate."] = "Du regenerierst nach und nach Gesundheit, sogar im Kampf.",
	["Recuperas vida y maná más rápido cuando no lanzas hechizos."] = "Du regenerierst Gesundheit und Mana schneller, wenn du nicht zauberst.",
	["Recurso"] = "Ressource",
	["Reduce el daño físico que recibes."] = "Senkt den körperlichen Schaden, den du nimmst.",
	["Registro de pesca nuevo."] = "Neues Angelprotokoll begonnen.",
