	["Reliquia"] = "Relikt",
	["Repara"] = "Repariert",
	["Repara con un herrero o un vendedor que repare antes de que se rompa."] = "Repariere bei einem Schmied oder einem Händler, der repariert, bevor es kaputtgeht.",
	["Reparación"] = "Reparatur",
	["Reparar"] = "Reparieren",
	["Repasar mis respuestas"] = "Meine Antworten ansehen",
	["Repetir a lo más cada"] = "Höchstens wiederholen alle",
	["Repetir el asistente"] = "Einrichtung wiederholen",
